 CREATE TEMP TABLE IF NOT EXISTS _routed_player_funding(period_id uuid,payer_kind text,payer_user uuid,payer_entity uuid,owed numeric,club_id uuid,funded_from text,destination_kind text,typed_wallet boolean,wallet_user uuid,cascade_key text,PRIMARY KEY(period_id,payer_kind,payer_entity,destination_kind)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_funding;
 INSERT INTO pg_temp._routed_player_funding SELECT i.period_id,fp.payer_kind,fp.payer_user,fp.payer_entity,fp.owed,i.club_id,
  CASE WHEN fp.payer_kind='club' OR fp.payer_user IS NULL OR fp.payer_user=owner_club.owner_id THEN CASE WHEN cascade.key IS NOT NULL THEN 'agent_wallet' ELSE 'club_treasury' END ELSE 'agent_wallet' END,fp.destination_kind,EXISTS(SELECT FROM public.accounting_rakeback_wallet_contracts wc WHERE wc.calculation_id=i.certificate_id),
  CASE WHEN fp.payer_kind='club' OR fp.payer_user IS NULL OR fp.payer_user=owner_club.owner_id THEN CASE WHEN cascade.key IS NOT NULL THEN owner_club.owner_id END ELSE fp.payer_user END,cascade.key
 FROM pg_temp._routed_player_todo i JOIN public.clubs owner_club ON owner_club.id=i.club_id
 CROSS JOIN LATERAL smarter_private.rakeback_certificate_wallets(i.certificate_id)fp
 -- OWNER UPLINE ROUTE (20261109): a share recorded for the club owner as upline
 -- is paid from the owner's agent wallet when, and only when, this week's
 -- funding cascade put exactly that money there. Otherwise nothing changes.
 LEFT JOIN LATERAL(SELECT smarter_private.rakeback_cascade_owner_route(i.certificate_id,i.club_id,owner_club.owner_id,fp.payer_user,from_date) AS key
  WHERE fp.owed>0 AND fp.destination_kind='player_wallet' AND(fp.payer_kind='club' OR fp.payer_user IS NULL OR fp.payer_user=owner_club.owner_id))cascade ON true;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_todo i WHERE i.owed IS DISTINCT FROM(SELECT sum(fp.owed)FROM pg_temp._routed_player_funding fp WHERE fp.period_id=i.period_id))
 THEN RAISE EXCEPTION 'routed_rakeback_payer_funding_not_conserved' USING ERRCODE='23514'; END IF;
