 PERFORM set_config('app.ledger_autoskip_clubs',COALESCE(club_skip,''),true);PERFORM set_config('app.ledger_autoskip_club_members',COALESCE(member_skip,''),true);PERFORM set_config('app.ledger_autoskip_agents',COALESCE(agent_skip,''),true);
 PERFORM set_config('app.deleted_wallet_routing_stage',COALESCE(deleted_deferral,''),true);
 CREATE TEMP TABLE IF NOT EXISTS _routed_split_returns(club_id uuid,user_id uuid,returned numeric,PRIMARY KEY(club_id,user_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_split_returns;
 INSERT INTO pg_temp._routed_split_returns(club_id,user_id,returned)
 SELECT lr.club_id,lr.horse_id,sum(lr.amount)-b.returned FROM public.ca_horse_club_split_late_returns lr
  JOIN pg_temp._routed_player_wallets pw ON pw.club_id=lr.club_id AND pw.user_id=lr.horse_id
  JOIN pg_temp._routed_split_return_openings b ON b.club_id=lr.club_id AND b.user_id=lr.horse_id
  GROUP BY lr.club_id,lr.horse_id,b.returned;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_wallets w JOIN public.club_members cm ON cm.club_id=w.club_id AND cm.user_id=w.user_id
   LEFT JOIN pg_temp._routed_split_returns sr ON sr.club_id=w.club_id AND sr.user_id=w.user_id
   WHERE cm.chip_balance IS DISTINCT FROM w.opening+w.delta-COALESCE(sr.returned,0))
 THEN RAISE EXCEPTION 'routed_rakeback_final_balance_incorrect' USING ERRCODE='23514',
   DETAIL=left('final_balance_disagreements: '||COALESCE((SELECT jsonb_agg(jsonb_build_object('club',w.club_id,'user',w.user_id,'opening',w.opening,'delta',w.delta,'split_returned',COALESCE(sr.returned,0),'actual',cm.chip_balance,'off_by',round(cm.chip_balance-(w.opening+w.delta-COALESCE(sr.returned,0)),2)) ORDER BY abs(cm.chip_balance-(w.opening+w.delta-COALESCE(sr.returned,0))) DESC) FROM pg_temp._routed_player_wallets w JOIN public.club_members cm ON cm.club_id=w.club_id AND cm.user_id=w.user_id LEFT JOIN pg_temp._routed_split_returns sr ON sr.club_id=w.club_id AND sr.user_id=w.user_id WHERE cm.chip_balance IS DISTINCT FROM w.opening+w.delta-COALESCE(sr.returned,0))::text,'none'),3200); END IF;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_agent_wallets w LEFT JOIN public.agents a ON a.club_id=w.club_id AND a.user_id=w.user_id
   WHERE a.agent_wallet_balance IS DISTINCT FROM w.opening+w.delta)
 THEN RAISE EXCEPTION 'routed_rakeback_final_agent_wallet_incorrect' USING ERRCODE='23514',
   DETAIL=left('final_balance_disagreements: '||COALESCE((SELECT jsonb_agg(jsonb_build_object('club',w.club_id,'user',w.user_id,'opening',w.opening,'delta',w.delta,'actual',a.agent_wallet_balance,'off_by',round(COALESCE(a.agent_wallet_balance,0)-(w.opening+w.delta),2)) ORDER BY abs(COALESCE(a.agent_wallet_balance,0)-(w.opening+w.delta)) DESC) FROM pg_temp._routed_agent_wallets w LEFT JOIN public.agents a ON a.club_id=w.club_id AND a.user_id=w.user_id WHERE a.agent_wallet_balance IS DISTINCT FROM w.opening+w.delta)::text,'none'),3200); END IF;
 -- All original transfer, invoice and net-wallet checks above still decide
 -- whether this stage may finish. Return only free net chips afterward,
 -- retaining published unpaid player obligations across bounded chunks.
 FOR v_deleted IN
  SELECT cm.club_id,cm.user_id FROM public.club_members cm
  JOIN public.profiles dp ON dp.id=cm.user_id AND dp.status='deleted'
  WHERE EXISTS(SELECT FROM pg_temp._routed_player_wallets w WHERE w.club_id=cm.club_id AND w.user_id=cm.user_id) AND EXISTS(SELECT FROM pg_temp._routed_player_todo t JOIN pg_temp._routed_player_now done ON done.period_id=t.period_id WHERE t.club_id=cm.club_id AND t.user_id=cm.user_id) ORDER BY cm.club_id,cm.user_id
 LOOP
  SELECT cm.chip_balance,coalesce(cm.held_chips,0),coalesce(cm.locked_chips,0)
   INTO STRICT v_deleted_before,v_deleted_held,v_deleted_locked FROM public.club_members cm
   WHERE cm.club_id=v_deleted.club_id AND cm.user_id=v_deleted.user_id;
  SELECT dwr_bank.chip_treasury INTO STRICT v_deleted_bank FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id;
  v_deleted_return:=public.fn_ca_deleted_wallet_bank_return(v_deleted.club_id,v_deleted.user_id,'player_wallet');
  IF v_deleted_return->'success' IS DISTINCT FROM 'true'::jsonb
   OR v_deleted_return->>'reserved_rakeback' IS NULL OR (v_deleted_return->>'reserved_rakeback')::numeric<0
   OR (v_deleted_return->>'reserved_rakeback')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (v_deleted_return->>'amount')::numeric IS DISTINCT FROM greatest(v_deleted_before-v_deleted_held-v_deleted_locked-(v_deleted_return->>'reserved_rakeback')::numeric,0)
   OR (v_deleted_return->>'player_chips')::numeric IS DISTINCT FROM (v_deleted_return->>'amount')::numeric
   OR (v_deleted_return->>'agent_chips')::numeric IS DISTINCT FROM 0::numeric
   OR NOT EXISTS(SELECT FROM public.club_members cm WHERE cm.club_id=v_deleted.club_id AND cm.user_id=v_deleted.user_id
     AND cm.chip_balance=v_deleted_before-(v_deleted_return->>'amount')::numeric
     AND coalesce(cm.held_chips,0)=v_deleted_held AND coalesce(cm.locked_chips,0)=v_deleted_locked)
   OR NOT EXISTS(SELECT FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id AND dwr_bank.chip_treasury=v_deleted_bank+(v_deleted_return->>'amount')::numeric)
  THEN RAISE EXCEPTION 'deleted_weekly_net_bank_return_not_conserved' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR v_deleted IN
  SELECT a.club_id,a.user_id FROM public.agents a
  JOIN public.profiles dp ON dp.id=a.user_id AND dp.status='deleted'
  WHERE EXISTS(SELECT FROM pg_temp._routed_agent_wallets w WHERE w.club_id=a.club_id AND w.user_id=a.user_id)
   AND EXISTS(SELECT FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now done ON done.period_id=f.period_id
    WHERE f.club_id=a.club_id AND ((f.funded_from='agent_wallet' AND f.wallet_user=a.user_id) OR(f.destination_kind='agent_wallet' AND EXISTS(SELECT FROM pg_temp._routed_player_todo t WHERE t.period_id=f.period_id AND t.user_id=a.user_id)))) ORDER BY a.club_id,a.user_id
 LOOP
  SELECT a.agent_wallet_balance INTO STRICT v_deleted_before FROM public.agents a
   WHERE a.club_id=v_deleted.club_id AND a.user_id=v_deleted.user_id;
  SELECT dwr_bank.chip_treasury INTO STRICT v_deleted_bank FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id;
  v_deleted_return:=public.fn_ca_deleted_wallet_bank_return(v_deleted.club_id,v_deleted.user_id,'agent_wallet');
  IF v_deleted_return->'success' IS DISTINCT FROM 'true'::jsonb
   OR v_deleted_return->>'reserved_rakeback' IS NULL OR (v_deleted_return->>'reserved_rakeback')::numeric<0
   OR (v_deleted_return->>'reserved_rakeback')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (v_deleted_return->>'amount')::numeric IS DISTINCT FROM greatest(v_deleted_before-(v_deleted_return->>'reserved_rakeback')::numeric,0)
   OR (v_deleted_return->>'agent_chips')::numeric IS DISTINCT FROM (v_deleted_return->>'amount')::numeric
   OR (v_deleted_return->>'player_chips')::numeric IS DISTINCT FROM 0::numeric
   OR NOT EXISTS(SELECT FROM public.agents a WHERE a.club_id=v_deleted.club_id AND a.user_id=v_deleted.user_id
     AND a.agent_wallet_balance=v_deleted_before-(v_deleted_return->>'amount')::numeric)
   OR NOT EXISTS(SELECT FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id AND dwr_bank.chip_treasury=v_deleted_bank+(v_deleted_return->>'amount')::numeric)
  THEN RAISE EXCEPTION 'deleted_weekly_net_bank_return_not_conserved' USING ERRCODE='23514'; END IF;
 END LOOP;
 PERFORM set_config('app.accounting_routing_context',COALESCE(routing_context,''),true);

 IF v_remaining>0 THEN
  RETURN jsonb_build_object('success',false,'batch_committed',true,'round',3,'routing_version',3,'source_version',2,'scope_kind',p_scope_kind,'scope_id',p_scope_id,
   'periods',(SELECT count(*) FROM pg_temp._routed_player_items),'paid_periods',(SELECT count(*) FROM pg_temp._routed_player_done)+(SELECT count(*) FROM pg_temp._routed_player_now),
   'remaining',v_remaining,'source_fingerprint',fingerprint,'plan_used',v_plan_used);
 END IF;
 -- The round's totals include what earlier batches of it paid.
 SELECT COALESCE(sum(i.owed),0),count(*) INTO v_paid_before,v_payees_before FROM pg_temp._routed_player_items i
  JOIN pg_temp._routed_player_done d ON d.period_id=i.period_id WHERE i.owed>0;
 paid:=paid+v_paid_before;payees:=payees+v_payees_before;
 result:=jsonb_build_object('success',true,'round',3,'name','certified_payer_to_players','routing_version',3,'source_version',2,'source_contract_version',3,'scope_kind',p_scope_kind,'scope_id',p_scope_id,
  'amount',paid,'payees',payees,'shortfalls',0,'periods',(SELECT count(*) FROM pg_temp._routed_player_items),'detail','[]'::jsonb);
 result:=result||jsonb_build_object('existing_transfer_economic_plan',smarter_private.existing_rakeback_transfer_scope_economic_plan(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player'),
  'existing_transfer_receipts',smarter_private.existing_rakeback_transfer_scope_receipts(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player'));
 club_partial:=smarter_private.weekly_payout_club_round_close(p_scope_kind,p_scope_id,p_period_start,p_period_end,3,fingerprint);
 IF club_partial IS NOT NULL THEN RETURN club_partial||jsonb_build_object('amount_paid_so_far',paid,'payees_so_far',payees); END IF;
 INSERT INTO public.accounting_routed_settlement_runs(union_id,standalone_club_id,period_start,period_end,round_no,source_fingerprint,result)
  VALUES(p_union_id,standalone_club,p_period_start,p_period_end,3,fingerprint,result);
 RETURN result;
END $function$

public.fn_stamp_accounting_tournament_fe.def:
CREATE OR REPLACE FUNCTION public.fn_stamp_accounting_tournament_fee(p_rake_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.rake_records%ROWTYPE;t record;e record;tp record;item record;reserve_id uuid;
 manifest jsonb;contributors jsonb:='[]';game_union uuid;expected_entitlement text;
 expected_category text;uid uuid;reg uuid;count_rows int;cutoff timestamptz;legacy boolean:=false;
BEGIN
 SELECT * INTO r FROM public.rake_records WHERE id=p_rake_record_id FOR UPDATE;
 IF NOT FOUND OR NOT r.is_tournament OR r.rake_amount<=0 THEN
  RAISE EXCEPTION 'positive_chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id) THEN
  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id AND status='legacy_unverified') THEN
   RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false);
  END IF;
  RETURN public.fn_capture_accounting_tournament_fee(r.id);
 END IF;
 SELECT starts_at INTO cutoff FROM public.accounting_tournament_fee_cutover WHERE singleton;
 IF r.created_at IS DISTINCT FROM transaction_timestamp() OR cutoff IS NULL OR r.created_at<cutoff THEN
  RAISE EXCEPTION 'tournament_fee_not_captured_by_original_producer' USING ERRCODE='55000'; END IF;
 SELECT id,club_id,union_id,is_private,tournament_type INTO t FROM public.tournaments WHERE id=r.tournament_id FOR SHARE;
 IF NOT FOUND OR public.fn_poker_diamond_tournament(r.tournament_id) THEN
  RAISE EXCEPTION 'chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 game_union:=CASE WHEN t.is_private THEN NULL ELSE t.union_id END;
 IF r.source='fn_spin_book_entry' THEN
  IF jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3 THEN
   RAISE EXCEPTION 'spin_fee_exact_paid_contributors_required' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT key::uuid player_id,value::numeric weight FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
   SELECT * INTO tp FROM public.tournament_players WHERE tournament_id=r.tournament_id AND user_id=item.player_id;
   IF NOT FOUND OR tp.club_id IS NULL THEN RAISE EXCEPTION 'spin_fee_entry_club_missing' USING ERRCODE='23514'; END IF;
   SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
    WHERE x.tournament_id=r.tournament_id AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge'
     AND x.charge_category='tournament_buyin' AND x.created_at=tp.registered_at AND x.gross=item.weight;
   IF count_rows<>1 THEN RAISE EXCEPTION 'spin_fee_exact_charge_ambiguous' USING ERRCODE='23514'; END IF;
   SELECT * INTO e FROM public.tournament_refund_entitlements x
    WHERE x.tournament_id=r.tournament_id AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge'
     AND x.charge_category='tournament_buyin' AND x.created_at=tp.registered_at AND x.gross=item.weight;
   contributors:=contributors||jsonb_build_array(jsonb_build_object('player_id',e.user_id,'club_id',e.refund_wallet_club_id,
    'registration_id',tp.id,'charge_ledger_id',e.source_ledger_id,'entitlement_id',e.id,'charged_at',e.created_at,'weight',item.weight));
   legacy:=legacy OR e.created_at<cutoff;
  END LOOP;
  SELECT count(*) INTO count_rows FROM public.spin_reserve_ledger s WHERE s.tournament_id=r.tournament_id AND s.kind='contribution';
  IF count_rows<>1 THEN RAISE EXCEPTION 'spin_fee_exact_reserve_required' USING ERRCODE='23514'; END IF;
  SELECT id INTO reserve_id FROM public.spin_reserve_ledger s WHERE s.tournament_id=r.tournament_id AND s.kind='contribution';
 ELSE
  IF NOT COALESCE(r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false) THEN
   RAISE EXCEPTION 'tournament_fee_exact_player_required' USING ERRCODE='23514'; END IF;
  uid:=(r.metadata->>'user_id')::uuid;
  expected_entitlement:=CASE r.source WHEN 'fn_register_for_tournament' THEN 'wallet_charge'
   WHEN 'fn_register_horse_for_tournament' THEN 'wallet_charge' WHEN 'process_tournament_rebuy' THEN 'wallet_charge'
   WHEN 'fn_award_satellite_seat' THEN 'satellite_seat' WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket' END;
  expected_category:=CASE WHEN r.source='process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
  IF expected_entitlement IS NULL THEN RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE='55000'; END IF;
  reg:=NULLIF(r.metadata->>'registration_id','')::uuid;
  IF reg IS NULL AND r.source='process_tournament_rebuy' THEN
   SELECT id INTO reg FROM public.tournament_players WHERE tournament_id=r.tournament_id AND user_id=uid;
  END IF;
  IF reg IS NULL THEN RAISE EXCEPTION 'tournament_fee_exact_registration_required' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
   WHERE x.tournament_id=r.tournament_id AND x.user_id=uid AND x.created_at=r.created_at AND x.refund_fee=r.rake_amount
    AND x.entitlement_kind=expected_entitlement
    AND (CASE WHEN expected_entitlement='wallet_charge' THEN x.charge_category=expected_category ELSE x.registration_id=reg END);
  IF count_rows<>1 THEN RAISE EXCEPTION 'tournament_fee_exact_charge_ambiguous' USING ERRCODE='23514'; END IF;
  SELECT * INTO e FROM public.tournament_refund_entitlements x
   WHERE x.tournament_id=r.tournament_id AND x.user_id=uid AND x.created_at=r.created_at AND x.refund_fee=r.rake_amount
    AND x.entitlement_kind=expected_entitlement
    AND (CASE WHEN expected_entitlement='wallet_charge' THEN x.charge_category=expected_category ELSE x.registration_id=reg END);
  contributors:=jsonb_build_array(jsonb_build_object('player_id',e.user_id,'club_id',e.refund_wallet_club_id,
   'registration_id',reg,'charge_ledger_id',e.source_ledger_id,'entitlement_id',e.id,'charged_at',e.created_at,'weight',r.rake_amount));
 END IF;
 IF legacy THEN
  INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,status)
   VALUES(r.id,r.tournament_id,public.fn_accounting_tournament_fee_fingerprint(r),r.rake_amount,'legacy_unverified');
  RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false);
 END IF;
 manifest:=jsonb_build_object('union_id',game_union,'game_type',lower(t.tournament_type),'contributors',contributors,'spin_reserve_id',reserve_id);
 -- Original tournament evidence may already be sealed by a satellite receipt.
 -- Capture its manifest on the accounting batch; never rewrite that raw row.
 BEGIN
  RETURN public.fn_capture_accounting_tournament_fee(r.id,manifest);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  -- Missing observed agreement may not destroy a proved original fee charge.
  -- This subtransaction rolls back every contributor receipt before recording
  -- the entire batch as unavailable. No partial commission can become payable.
  IF SQLERRM NOT IN('accounting_terms_not_observed','accounting_terms_not_active') THEN RAISE; END IF;
  INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,status,source_manifest)
   VALUES(r.id,r.tournament_id,public.fn_accounting_tournament_fee_fingerprint(r),r.rake_amount,'legacy_unverified',
    manifest||jsonb_build_object('capture_reason',SQLERRM));
  RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false,'reason',SQLERRM);
 END;
END $function$

public.fn_sync_seat_first_player_count(p.def:
CREATE OR REPLACE FUNCTION public.fn_sync_seat_first_player_count(p_tournament_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table      uuid;
  v_seats      integer := 0;
  v_seat_first boolean := false;
  v_is_spin    boolean := false;
  v_cap        integer := 0;
  v_variant    text := '';
  v_book       jsonb;
BEGIN
  -- This is an AFTER-seat helper. It must never acquire a new global lock
  -- after PostgreSQL already owns the changed seat row. Every legitimate
  -- create/revive root pre-acquires terminal -> mission -> launch -> tournament,
  -- and the earliest BEFORE trigger refuses a raw writer that did not.
  SELECT public.fn_ca_tournament_recorded_seat_first(t.id, true),
         t.format_contract = 'spin-v1',
         COALESCE(t.max_players, 0),
         COALESCE(t.variant, '')
    INTO v_seat_first, v_is_spin, v_cap, v_variant
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Freeze the complete table/seat set before choosing the occupied table.
  -- UUID order is deterministic across every transaction using this owner.
  PERFORM tb.id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
   ORDER BY tb.id
   FOR UPDATE;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
     AND s.left_at IS NULL
   ORDER BY s.table_id, s.seat_number, s.id
   FOR UPDATE OF s;

  v_table := public.fn_tournament_primary_table(p_tournament_id);

  IF v_table IS NULL THEN
    IF COALESCE(v_seat_first, false) THEN
      SELECT count(*) INTO v_seats
        FROM public.table_seats s
        JOIN public.tables tb ON tb.id = s.table_id
       WHERE tb.tournament_id = p_tournament_id
         AND s.left_at IS NULL;
      UPDATE public.tournaments SET current_players = v_seats
       WHERE id = p_tournament_id
         AND current_players IS DISTINCT FROM v_seats;
      RETURN v_seats;
    END IF;
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_seats
    FROM public.table_seats
   WHERE table_id = v_table AND left_at IS NULL;

  UPDATE public.tables SET current_players = v_seats
   WHERE id = v_table
     AND current_players IS DISTINCT FROM v_seats;

  IF COALESCE(v_seat_first, false) THEN
    UPDATE public.tournaments SET current_players = v_seats
     WHERE id = p_tournament_id
       AND current_players IS DISTINCT FROM v_seats;
  END IF;

  -- DIAMOND PHASE 9: a Diamond Spin's three entries are already whole in
  -- custody; its reserve legs are booked at its draw, against its source.
  IF v_is_spin AND v_cap > 0 AND v_seats >= v_cap
     AND NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    v_book := public.fn_spin_book_entry(p_tournament_id);
    IF COALESCE((v_book->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'paid third seat could not book Spin %: %',
        p_tournament_id,v_book USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF COALESCE(v_seat_first, false)
     AND v_cap > 0 AND v_seats >= v_cap THEN
    BEGIN
      PERFORM realtime.send(
        jsonb_build_object(
          'tournament_id', p_tournament_id,
          'variant', v_variant,
          'max_players', v_cap,
          'paid_seats', v_seats,
          'filled_at', now()
        ),
        'seat_first_ready',
        'seat_first',
        false
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING
        'fn_sync_seat_first_player_count: realtime.send failed for %: %',
        p_tournament_id, SQLERRM;
    END;
  END IF;

  RETURN v_seats;
END;
$function$

public.fn_take_seat_and_buy_in_before_ma.def:
CREATE OR REPLACE FUNCTION public.fn_take_seat_and_buy_in_before_maintenance_announcement_gate(p_table_id uuid, p_seat_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid        uuid := auth.uid();
  v_tbl        record;
  v_t          record;
  v_reg        jsonb;
  v_seat_cap   integer;
  v_taken      integer;
  v_mine       integer;
  v_stack      numeric;
  v_err        text;
BEGIN
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  PERFORM set_config('app.money_path', 'fn_take_seat_and_buy_in', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)
  -- ── A DEAD SESSION MOVES NO MONEY (Dan 2026-09-03) ────────────────────
  -- "I WAS LOGGED OUT, BUT SOMEHOW ABLE TO SIT DOWN AND BUY CHIPS AND GET
  -- DEALT A HAND. THAT CAN NEVER HAPPEN." It could, because this project
  -- issues SEVEN-DAY access tokens and PostgREST verifies a JWT locally -
  -- signature and exp only. It never asks GoTrue whether the session behind
  -- that token still exists, so signing out left a bearer token that kept
  -- spending real chips as its owner for the rest of the week. The engine
  -- was never fooled (it verifies through auth.getUser, which checks the
  -- session), only the database was. fn_caller_session_is_live closes that
  -- gap at the money door itself.
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_take_seat_and_buy_in requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  SELECT id, tournament_id, max_players, status
    INTO v_tbl FROM public.tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_tbl.tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_game_table');
  END IF;
  IF v_tbl.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_closed');
  END IF;

  SELECT id, status, variant, max_players, starting_chips, name
    INTO v_t FROM public.tournaments WHERE id = v_tbl.tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
  END IF;

  IF NOT public.fn_ca_tournament_recorded_seat_first(v_t.id, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_seat_first_game');
  END IF;

  -- The chips this seat is buying. Known now, because the board decides it.
  v_stack := COALESCE(v_t.starting_chips, 0);

  v_seat_cap := COALESCE(NULLIF(v_tbl.max_players, 0), v_t.max_players, 3);

  IF p_seat_number IS NULL OR p_seat_number < 1 OR p_seat_number > v_seat_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_seat');
  END IF;

  SELECT seat_number INTO v_mine
    FROM public.table_seats
   WHERE table_id = p_table_id AND user_id = v_uid AND left_at IS NULL LIMIT 1;
  IF v_mine IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'already_seated', true,
      'table_id', p_table_id, 'seat_number', v_mine);
  END IF;

  IF v_t.status NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_already_started');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.table_seats
     WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
  END IF;

  PERFORM public.fn_sync_seat_first_player_count(v_t.id);

  v_reg := public.fn_register_for_tournament(v_t.id, true);
  IF COALESCE((v_reg->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE(v_reg->>'reason', '') <> 'already_registered' THEN
    RETURN jsonb_build_object('ok', false,
      'reason', COALESCE(v_reg->>'reason', 'buy_in_failed'));
  END IF;

  UPDATE public.tournament_players
     SET status = 'playing', chips = v_stack, table_id = p_table_id, seat_number = p_seat_number
   WHERE tournament_id = v_t.id AND user_id = v_uid;

  UPDATE public.table_seats
     SET user_id = v_uid, stack = v_stack, left_at = NULL, joined_at = now(), is_sitting_out = false
   WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NOT NULL;

  IF NOT FOUND THEN
    BEGIN
      INSERT INTO public.table_seats (table_id, user_id, seat_number, stack)
      VALUES (p_table_id, v_uid, p_seat_number, v_stack);
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'seat_taken' USING ERRCODE = '55000';
    END;
  END IF;

  v_taken := COALESCE(public.fn_sync_seat_first_player_count(v_t.id), 0);
  IF v_taken = 0 THEN
    SELECT count(*) INTO v_taken FROM public.table_seats
     WHERE table_id = p_table_id AND left_at IS NULL;
  END IF;

  RETURN jsonb_build_object('ok', true, 'table_id', p_table_id,
    'seat_number', p_seat_number, 'stack', v_stack, 'seat_reserved', true,
    'seats_taken', v_taken, 'seats_needed', v_seat_cap,
    'starts_now', v_taken >= v_seat_cap,
    'cost', COALESCE((v_reg->>'cost')::numeric, 0))
    -- DIAMOND PHASE 8: a Diamond seat purchase names its asset and the
    -- wallet after the charge, as the lobby receipt does, so the client can
    -- move the balance it shows. Absent on the already_registered answer,
    -- which carries no charge.
    || CASE WHEN v_reg ? 'asset'
         THEN jsonb_build_object('asset', v_reg->'asset', 'diamonds_after', v_reg->'diamonds_after')
         ELSE '{}'::jsonb END;

EXCEPTION
  WHEN sqlstate '55000' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
  WHEN sqlstate '23514' THEN
    GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
    IF v_err LIKE '%FOUR TABLE LIMIT%' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'table_limit_reached',
        'limit', 4);
    END IF;
    RAISE;
END;
$function$

public.fn_terminal_bounty_recipient_is_i.def:
CREATE OR REPLACE FUNCTION public.fn_terminal_bounty_recipient_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.award_id IS DISTINCT FROM OLD.award_id THEN
    RAISE EXCEPTION 'bounty recipient award ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT a.tournament_id INTO v_old_tournament_id
      FROM public.tournament_bounty_awards a WHERE a.id = OLD.award_id;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT a.tournament_id INTO v_new_tournament_id
      FROM public.tournament_bounty_awards a WHERE a.id = NEW.award_id;
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION 'new bounty recipient cannot supply a terminal marker'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_old_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'bounty recipient terminal marker transition is not canonical'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_tournament_entry_cap_reached(p.def:
CREATE OR REPLACE FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cap      integer;
  v_counter  integer;
  v_entries  integer;
BEGIN
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  SELECT t.max_players, COALESCE(t.current_players, 0)
    INTO v_cap, v_counter
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;

  IF NOT FOUND OR public.fn_ca_tournament_is_unlimited(p_tournament_id)
     OR v_cap IS NULL OR v_cap <= 0 THEN
    RETURN false;                      -- uncapped: this function never refuses
  END IF;

  SELECT count(*) INTO v_entries
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* GREATEST, never the entry count alone: this can only ever be stricter than
     the counter test it replaces, never looser. */
  RETURN GREATEST(v_counter, COALESCE(v_entries, 0)) >= v_cap;
END;
$function$

public.fn_union_eco_components(p_union_i.def:
CREATE OR REPLACE FUNCTION public.fn_union_eco_components(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE terms jsonb;proof jsonb;basis jsonb;club jsonb;club_basis jsonb;output jsonb:='[]';n integer;
BEGIN
 IF auth.uid()IS NULL AND COALESCE(auth.role(),'')<>'service_role'AND session_user NOT IN('postgres','supabase_admin')THEN RAISE EXCEPTION 'ECO authentication required' USING ERRCODE='42501';END IF;
 -- Preserve exactly the original ECO disclosure boundary for nested invoices.
 IF auth.uid()IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM public.unions u WHERE u.id=p_union_id AND u.owner_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM public.union_admins ua WHERE ua.union_id=p_union_id AND ua.user_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM public.union_clubs uc JOIN public.club_members cm ON cm.club_id=uc.club_id
   WHERE uc.union_id=p_union_id AND cm.user_id=auth.uid()AND cm.role IN('owner','co_owner','admin','super_agent'))THEN
  RAISE EXCEPTION 'not authorized to read union ECO' USING ERRCODE='42501';END IF;
 PERFORM smarter_private.union_eco_terms_for_book(p_union_id,p_start,p_end);
 IF EXISTS(SELECT FROM smarter_private.union_eco_components WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end)THEN
  FOR club IN SELECT DISTINCT jsonb_build_object('club_id',club_id)FROM smarter_private.union_eco_components WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end LOOP
   PERFORM smarter_private.union_eco_invoice_components(p_union_id,(club->>'club_id')::uuid,p_start,p_end);
  END LOOP;
  IF EXISTS(SELECT club_id FROM smarter_private.union_eco_components WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end GROUP BY club_id HAVING count(*)<>2)THEN
   RAISE EXCEPTION 'original_eco_recorded_activity_pair_incomplete' USING ERRCODE='55000';END IF;
  SELECT jsonb_agg(jsonb_build_object('club_id',x.club_id,'eco_version',2,'eco_components',x.components,'eco_amount',x.amount)ORDER BY x.club_id)
   INTO output FROM(SELECT club_id,sum(amount)amount,jsonb_agg(jsonb_build_object('activity',activity,'enabled',enabled,'base_mode',base_mode,
    'base',base,'rate',rate,'amount',amount,'terms_id',terms_id,'record_id',id,'status','recorded')ORDER BY activity)components
    FROM smarter_private.union_eco_components WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end GROUP BY club_id)x;
  RETURN jsonb_build_object('status','ready','eco_version',2,'clubs',output,'period_start',p_start,'period_end',p_end);
 END IF;
 -- A historical scalar is authoritative, but cannot be reverse-engineered into two facts.
 IF EXISTS(SELECT FROM public.union_eco_ledger WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end)THEN
  SELECT jsonb_agg(jsonb_build_object('club_id',club_id,'eco_version',1,'eco_components',NULL,'eco_amount',eco_amount)ORDER BY club_id)
   INTO output FROM public.union_eco_ledger WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end;
  RETURN jsonb_build_object('status','legacy_unavailable','eco_version',1,'clubs',output,'period_start',p_start,'period_end',p_end);
 END IF;
 terms:=smarter_private.union_eco_terms_for_book(p_union_id,p_start,p_end);
 IF terms IS NULL THEN RETURN jsonb_build_object('status','legacy_unavailable','eco_version',1,'eco_components',NULL,'clubs',NULL);END IF;
 proof:=public.fn_union_pnl_qualified_clubs(p_union_id,p_start,p_end);
 SELECT COALESCE(jsonb_agg(to_jsonb(b)),'[]')INTO basis FROM public.fn_union_club_rake_basis(p_union_id,p_start,p_end)b;
 FOR club IN SELECT x FROM jsonb_array_elements(proof->'clubs')x LOOP
  SELECT COALESCE(jsonb_agg(x),'[]')INTO club_basis FROM jsonb_array_elements(basis)x WHERE x->>'club_id'=club->>'club_id';
  output:=output||jsonb_build_array(smarter_private.union_eco_calculate(club,club_basis,terms));
 END LOOP;
 RETURN jsonb_build_object('status','ready','eco_version',2,'clubs',output,'period_start',p_start,'period_end',p_end,'terms_id',terms->'id');
END$function$

public.fn_union_eco_record(p_union_id uu.def:
CREATE OR REPLACE FUNCTION public.fn_union_eco_record(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_settlement_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE proof jsonb;c jsonb;component jsonb;basis jsonb;terms jsonb;n integer:=0;
BEGIN
 IF auth.uid()IS NOT NULL AND NOT EXISTS(SELECT FROM public.unions WHERE id=p_union_id AND owner_id=auth.uid())
  AND NOT EXISTS(SELECT FROM public.union_admins WHERE union_id=p_union_id AND user_id=auth.uid())THEN
  RETURN jsonb_build_object('success',false,'error','not authorized');END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('union-eco-components:'||p_union_id::text||':'||extract(epoch from p_start)::text,0))THEN
  RAISE EXCEPTION 'original_eco_book_already_owned' USING ERRCODE='55006';END IF;
 terms:=smarter_private.union_eco_terms_for_book(p_union_id,p_start,p_end);
 IF terms IS NOT NULL AND p_end>clock_timestamp()THEN RAISE EXCEPTION 'original_eco_book_not_closed' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT FROM smarter_private.union_eco_components WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end)THEN
  proof:=public.fn_union_eco_components(p_union_id,p_start,p_end);
  RETURN jsonb_build_object('success',true,'already_recorded',true,'eco_version',2,'clubs',jsonb_array_length(proof->'clubs'),'period_start',p_start,'period_end',p_end);
 END IF;
 IF EXISTS(SELECT FROM public.union_eco_ledger WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end)THEN
  RETURN jsonb_build_object('success',true,'already_recorded',true,'eco_version',1,'legacy_split_unavailable',true,'period_start',p_start,'period_end',p_end);END IF;
 terms:=smarter_private.union_eco_terms_for_book(p_union_id,p_start,p_end);
 IF terms IS NULL THEN RETURN smarter_private.union_eco_legacy_record(p_union_id,p_start,p_end,p_settlement_id);END IF;
 PERFORM public.fn_require_union_pnl_evidence(p_union_id,p_start,p_end);
 proof:=public.fn_union_eco_components(p_union_id,p_start,p_end);
 IF proof->>'status'IS DISTINCT FROM 'ready' OR proof->'eco_version'IS DISTINCT FROM '2'::jsonb THEN
  RAISE EXCEPTION 'original_eco_activity_basis_unqualified' USING ERRCODE='55000';END IF;
 FOR c IN SELECT x FROM jsonb_array_elements(proof->'clubs')x LOOP
  n:=n+1;
  FOR component IN SELECT x FROM jsonb_array_elements(c->'eco_components')x LOOP
   basis:=jsonb_build_object('version',2,'component',component,'terms',terms,'club_id',c->'club_id','period_start',p_start,'period_end',p_end,
    'financial_basis','unchanged_qualified_original_cash_and_realized_tournament_pnl','facts',c->'eco_facts',
    'financial_generation',smarter_private.original_inventory_basis_generation(),
    'club_roster',(SELECT jsonb_agg(x->'club_id'ORDER BY x->>'club_id')FROM jsonb_array_elements(proof->'clubs')x),
    'calculator_md5',md5(pg_get_functiondef('smarter_private.union_eco_calculate(jsonb,jsonb,jsonb)'::regprocedure)));
   INSERT INTO smarter_private.union_eco_components(union_id,club_id,period_start,period_end,activity,terms_id,enabled,base_mode,base,rate,amount,basis,basis_sha256,settlement_id)
   VALUES(p_union_id,(c->>'club_id')::uuid,p_start,p_end,component->>'activity',(component->>'terms_id')::uuid,(component->>'enabled')::boolean,
    'club_profit',(component->>'base')::numeric,(component->>'rate')::numeric,(component->>'amount')::numeric,basis,
    encode(extensions.digest(convert_to(basis::text,'UTF8'),'sha256'),'hex'),p_settlement_id);
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('success',true,'eco_version',2,'clubs',n,'components',2*n,'eco_base_mode','separate_club_profit','period_start',p_start,'period_end',p_end);
END$function$

public.fn_union_pnl_evidence_report(p_un.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_evidence_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_open jsonb; v_close jsonb; v_issues jsonb:='[]'; v_clubs jsonb; v_eco jsonb; v_terms jsonb;
 v_fence timestamptz; v_bad bigint; v_hands bigint; v_resolved bigint:=0; v_rows bigint; v_cash_reconciled boolean; v_terms_value jsonb; v_cash_rake numeric; v_accepted_rake numeric;
 v_memo_key text; v_memo jsonb; v_report jsonb; v_flows jsonb; v_open_resolved uuid[];
 v_inv boolean; v_cash boolean; v_credit boolean;
 v_cert jsonb; v_generation text;v_hand_parts jsonb;
 v_slice jsonb; v_slice_start timestamptz; v_slice_end timestamptz; v_slice_bad bigint;
 v_l_value jsonb;v_l_key jsonb;v_l_witness jsonb;v_l_counts jsonb;
 v_l_valid boolean;v_l_name text;v_l_number numeric;
 v_hand_projected boolean;v_l_snapshot jsonb;v_l_entry jsonb;v_l_complete boolean;
 v_l_checked_at timestamptz;v_l_rows numeric;v_l_bad numeric;v_l_resolved numeric;v_l_unknown numeric;
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_start<>public.fn_union_week_start(p_start) OR p_end<>public.fn_union_week_start(p_start+interval '8 days')
  OR p_end>clock_timestamp() THEN RAISE EXCEPTION 'invalid_closed_pnl_evidence_period' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO v_fence FROM public.union_pnl_weekly_capture WHERE singleton;
 IF v_fence IS NULL OR p_start<=v_fence THEN
  RETURN jsonb_build_object('report_version',1,'status','blocked','basis_certified',false,'payment_authorized',false,
   'issues',jsonb_build_array('week_precedes_complete_original_capture'),'capture_started_at',v_fence,'all_players_included',false);
 END IF;
 IF p_union_id='fade0000-0000-0000-0000-000000000001'::uuid AND p_end>='2026-10-12 07:00:00Z'::timestamptz THEN
  v_generation:=COALESCE(smarter_private.original_inventory_basis_generation(),'original-inventory-245:unqualified');
 END IF;
 -- UNION P&L EVIDENCE MEMO (20260928): one weekly close reaches this report
 -- through preparation (close quality), the cascade (qualified clubs, ECO,
 -- player P&L) and the invoices. Inside a union close attempt
 -- (app.accounting_close_memo='on', set only by fn_weekly_accounting_attempt_begin)
 -- the first complete report of this (union, week) is kept for the rest of
 -- the attempt; attempt_begin and attempt_end clear it and a rolled-back
 -- subtransaction forgets it with its settings. Everywhere else the report is
 -- proved on every call, exactly as before.
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  v_memo_key:=CASE WHEN v_generation='original-inventory-245:unqualified' THEN NULL ELSE COALESCE(v_generation||'|','')||p_union_id::text||'|'||p_start::text||'|'||p_end::text END;
  v_memo:=NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb;
  IF v_memo ? v_memo_key THEN RETURN v_memo->v_memo_key; END IF;
 END IF;
 -- UNION P&L NARROW READS (20260929044303): the week's registration events,
 -- hands and tournament credits are read through their narrow projections
 -- (union_pnl_inventory_touches, union_pnl_cash_outcome_touches,
 -- union_pnl_credit_touches), each written by its source row's own insert,
 -- once the throttled backfill has proved it complete; until then through
 -- the original wide rows, statement for statement as before.
 v_inv:=public.fn_union_pnl_projection_ready('inventory_touches');
 v_cash:=public.fn_union_pnl_projection_ready('cash_outcome_touches');
 v_credit:=public.fn_union_pnl_projection_ready('credit_touches');
 -- Both readers wait for the original book's in-flight transactions; this
 -- function is VOLATILE so every subsequent query sees their committed facts.
 -- CHUNKED CLOSE CERTIFICATES (20261003): inside a chunked union close attempt
 -- each expensive read below that found nothing wrong is kept, once proved,
 -- in accounting_close_certificates for the rest of that close of this
 -- closed week (fn_accounting_close_certificate / fn_accounting_close_certify;
 -- both do nothing anywhere else). An attempt whose time budget is spent
 -- after a step it had to prove returns 'warming' - not ready, nothing
 -- certified for payment - and the next attempt continues from the kept
 -- steps. A step that found a problem is kept for ONE HOUR (20261012), as
 -- '<kind>_problem' (fn_accounting_close_problem): it is never certified and
 -- never pays, its issues are reported exactly as before, and an attempt
 -- re-proves it once that hour has passed. Re-proving every problem step on
 -- every attempt is what held job 272's transactions for 3 to 5 minutes.
 v_open:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_start,p_start),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_start,p_start));
 IF v_open IS NULL THEN
  v_open:=public.fn_union_pnl_boundary(p_union_id,p_start);
  IF v_open->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_start,p_start,v_open);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_start,p_start,v_open); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 -- THE WINDOWS GO FIRST (20261012): the plan's two-hour windows (seconds each)
 -- are proved before the steps below, so an attempt that would otherwise
 -- spend its budget re-reading the boundaries and flows proves windows
 -- instead. Outside a chunked close the advance is NULL and nothing changes.
 IF public.fn_accounting_union_earned_plan_advance(p_union_id,p_start,p_end) IS FALSE THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_close:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_end,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_end,p_end));
 IF v_close IS NULL THEN
  v_close:=public.fn_union_pnl_boundary(p_union_id,p_end);
  IF v_close->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_end,p_end,v_close);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_end,p_end,v_close); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_open->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','opening_basis_incomplete','evidence',v_open)); END IF;
 IF v_close->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','closing_basis_incomplete','evidence',v_close)); END IF;
 -- The registrations the opening boundary carried through a valid opening
 -- resolution (union_pnl_opening_registration_resolutions): each one's
 -- original entry is proved from the posted chip ledger, not a funding receipt.
 v_open_resolved:=ARRAY(SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  WHERE x->>'kind'='deferred_tournament_result' AND x->>'basis'='opening_registration_resolution');
 -- A blocked outcome counts as accepted only through an immutable resolution
 -- receipt re-proved from primary receipts and bound to this exact outcome
 -- (hand, payload hash, evidence). The outcome row itself is never changed.
 -- Only a hand outside the ready/certified/all-players/same-scope shape can
 -- be refused or resolved: those hands (the predicate of
 -- union_pnl_cash_outcomes_unaccepted), found through the projection's shape
 -- flag and re-checked against their rows, never the whole week's evidence.
 SELECT count(*) FILTER(WHERE NOT public.fn_union_pnl_cash_outcome_accepted(o)),
  count(*) FILTER(WHERE (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb)
   AND public.fn_union_pnl_cash_outcome_accepted(o))
 INTO v_bad,v_resolved FROM public.fn_union_pnl_week_shaped_hands(p_union_id,p_start,p_end,v_cash) o;
 -- A hand whose provenance link the engine never recorded (its outcome has no
 -- game scope) counts only through its immutable link resolution
 -- (union_pnl_cash_outcome_link_resolutions), in the Union its re-proved scope
 -- names, and is accepted only when its re-proved evidence is certified.

 -- LINKED WINDOW ASSEMBLY: one source snapshot for ALL canonical windows,
 -- stored proofs and STABLE trusted witnesses; subsequent loop reads JSON only.
 v_l_snapshot:=NULL;v_l_complete:=false;v_l_bad:=0;v_l_resolved:=0;v_l_rows:=0;v_l_unknown:=0;
 IF current_setting('app.weekly_accounting_chunked',true)='on'
 AND current_setting('app.accounting_close_memo',true)='on'
 AND v_generation IS NOT NULL AND v_generation<>'original-inventory-245:unqualified'THEN
  WITH canonical AS MATERIALIZED(SELECT * FROM public.fn_accounting_close_windows(p_start,p_end)),
  proofs AS MATERIALIZED(SELECT p.* FROM public.accounting_close_partials p
   WHERE p.kind='pnl_linked_window'AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end),
  witnesses AS MATERIALIZED(SELECT w.window_start,w.window_end,
   smarter_private.weekly_hand_parts_witness(p_union_id,w.window_start,w.window_end,v_cash)witness FROM canonical w)
  SELECT jsonb_build_object('expected',(SELECT count(*)FROM canonical),'actual',(SELECT count(*)FROM proofs),
   'entries',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'key',jsonb_build_object('union_id',p_union_id::text,'period_start_epoch',extract(epoch FROM p_start),'period_end_epoch',extract(epoch FROM p_end),'window_start_epoch',extract(epoch FROM w.window_start),'window_end_epoch',extract(epoch FROM w.window_end)),
    'window_start',w.window_start,'window_end',w.window_end,'proof',to_jsonb(p),'witness',w.witness,
    'bounds_match',p.window_start=w.window_start AND p.window_end=w.window_end,
    'finite_time',isfinite(p.computed_at),
    'unused_null',p.cash_ids IS NULL AND p.cash_md5 IS NULL AND p.fee_ids IS NULL AND p.fee_md5 IS NULL)
    ORDER BY w.window_start,w.window_end),'[]'::jsonb)FROM witnesses w LEFT JOIN proofs p ON p.window_start=w.window_start))
  INTO v_l_snapshot;
  v_l_checked_at:=clock_timestamp();v_hand_projected:=v_cash;
  IF(v_l_snapshot->>'expected')::bigint>0
   AND v_l_snapshot->'expected'=v_l_snapshot->'actual'
   AND jsonb_array_length(v_l_snapshot->'entries')=(v_l_snapshot->>'expected')::bigint THEN
   v_l_complete:=true;
   FOR v_l_entry IN SELECT value FROM jsonb_array_elements(v_l_snapshot->'entries')LOOP
    IF v_l_entry->'bounds_match'IS DISTINCT FROM'true'::jsonb
     OR v_l_entry->'finite_time'IS DISTINCT FROM'true'::jsonb
     OR v_l_entry->'unused_null'IS DISTINCT FROM'true'::jsonb THEN v_l_complete:=false;EXIT;END IF;
    IF(v_l_entry#>>'{proof,computed_at}')::timestamptz<p_end
     OR(v_l_entry#>>'{proof,computed_at}')::timestamptz<=v_l_checked_at-public.fn_accounting_close_proof_lifetime()
     OR(v_l_entry#>>'{proof,computed_at}')::timestamptz>v_l_checked_at THEN v_l_complete:=false;EXIT;END IF;
    v_l_value:=v_l_entry#>'{proof,value}';v_l_key:=v_l_entry->'key';v_l_witness:=v_l_entry->'witness';

 v_l_valid:=false;
 IF jsonb_typeof(v_l_value)='object'
 AND v_l_value->>'contract'='canonical-linked-validation-v1'
 AND v_l_value->>'generation'=v_generation
 AND v_l_value->'projected'=to_jsonb(v_hand_projected)
 AND v_l_value->>'reader_md5'='21241121f4e4fe29a7becb1ff692d722'
 AND v_l_value->>'witness_md5'='a101812df22c1dfb379ebc325bd7d6d0'
 AND v_l_value->'input_key'=v_l_key
 AND v_l_value->'witness'=v_l_witness
 AND v_l_value->>'proof_md5'=md5((v_l_value-'proof_md5')::text)
 AND jsonb_typeof(v_l_value->'counts')='object' THEN
  v_l_counts:=v_l_value->'counts';v_l_valid:=true;
  IF(SELECT array_agg(key ORDER BY key)FROM jsonb_object_keys(v_l_counts)key)
    IS DISTINCT FROM ARRAY['bad','resolved','rows','unknown']THEN v_l_valid:=false;END IF;
  IF v_l_valid THEN
   FOREACH v_l_name IN ARRAY ARRAY['rows','bad','resolved','unknown']LOOP
    IF jsonb_typeof(v_l_counts->v_l_name)IS DISTINCT FROM'number'
     OR(v_l_counts->>v_l_name)!~'^[0-9]{1,19}$'THEN v_l_valid:=false;EXIT;END IF;
    v_l_number:=(v_l_counts->>v_l_name)::numeric;
    IF v_l_number>9223372036854775807 THEN v_l_valid:=false;EXIT;END IF;
   END LOOP;
  END IF;
  IF v_l_valid THEN
   IF (v_l_counts->>'rows')::numeric IS DISTINCT FROM
    (v_l_counts->>'bad')::numeric+(v_l_counts->>'resolved')::numeric+(v_l_counts->>'unknown')::numeric THEN v_l_valid:=false;END IF;
  END IF;
 END IF;

    IF NOT v_l_valid THEN v_l_complete:=false;EXIT;END IF;
    v_l_rows:=v_l_rows+(v_l_counts->>'rows')::numeric;v_l_bad:=v_l_bad+(v_l_counts->>'bad')::numeric;
    v_l_resolved:=v_l_resolved+(v_l_counts->>'resolved')::numeric;v_l_unknown:=v_l_unknown+(v_l_counts->>'unknown')::numeric;
   END LOOP;
   IF greatest(v_l_rows,v_l_bad,v_l_resolved,v_l_unknown)>9223372036854775807 THEN v_l_complete:=false;END IF;
  END IF;
 END IF;
 IF v_l_complete AND(v_l_unknown=0 OR v_l_bad>0)THEN
  -- A complete known-bad proof is used: preserve the blocked report, even if
  -- other rows have unknown readiness. Unknown-only uses original 3VL below.
  v_bad:=v_bad+v_l_bad::bigint;v_resolved:=v_resolved+v_l_resolved::bigint;
 ELSE
 SELECT v_bad+count(*) FILTER(WHERE NOT (k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)),
  v_resolved+count(*) FILTER(WHERE k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)
 INTO v_bad,v_resolved FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k;
 END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_basis_incomplete','count',v_bad)); END IF;
 -- A missing original game scope cannot silently disappear from every Union.
 SELECT count(*) INTO v_bad FROM public.union_pnl_cash_outcomes WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale']
  AND NOT EXISTS(SELECT 1 FROM public.fn_union_pnl_cash_outcome_link(union_pnl_cash_outcomes));
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_original_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.union_pnl_original_flows WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale'];
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_participant_funding_receipts WHERE recorded_at>=v_fence AND recorded_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_funding_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_funding_application_receipts WHERE applied_at>=v_fence AND applied_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_application_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_hand_provenance_receipts WHERE accepted_at>=v_fence AND accepted_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_hand_transaction_identity_missing'); END IF;
 -- The flow proof is read once; the P&L below reuses these exact rows.
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_flows',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_flows',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint; v_flows:=v_cert->'flows';
 ELSE
 SELECT count(*) FILTER(WHERE NOT f.valid),COALESCE(jsonb_agg(to_jsonb(f)),'[]') INTO v_bad,v_flows
  FROM public.fn_union_pnl_original_flow_evidence(p_union_id,p_start,p_end) f;
  IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows));
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_basis_incomplete','count',v_bad)); END IF;
 -- Every touched tournament registration must have its original chip entry,
 -- including zero-rake players. Historical/current membership is never used.
 -- The week's registration events, each touched tournament's Union proved
 -- once through its own events (t.row_id::text equality kept; the uuid
 -- equality only lets the index find the same rows and is never attempted on
 -- a non-canonical id). The frame test is unchanged; i.observed_at repeats it
 -- because fn_union_pnl_inventory_observe, the only writer of framed events,
 -- stamps each event with its frame's observed_at (both tables immutable), so
 -- the same rows are reached through union_pnl_inventory_events_players_observed.
 -- Both reads (fn_union_pnl_touched_registrations, fn_union_pnl_tournament_in_union)
 -- come from union_pnl_inventory_touches once it is complete: the same keys,
 -- the frame's observed_at copied at capture, without the wide rows.
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_touched',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_touched',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint;
 ELSE
 -- SUB-RANGE CERTIFIED TOUCHED STEP (20261110235631): this one statement
 -- cannot fit a 4 minute scope budget. Two of its joins are CTE scan nested
 -- loops, so its cost is quadratic in the rows of the period: measured on the
 -- week of 2026-11-02, 204,675,344 then 1,182,765,165 join filter evaluations
 -- for a single 6 hour slice. The week is therefore proved in 3 hour
 -- sub-ranges, each certified under the SAME 'pnl_touched' kind at its own
 -- narrower (start,end) key, and summed. 'bad' is a count of touch rows, the
 -- two range predicates of fn_union_pnl_touched_registrations are the same
 -- predicate (fn_union_pnl_inventory_observe stamps every event with its
 -- frame's observed_at and is the only writer), and a row's verdict has no
 -- period dependence, so the sum over any contiguous half-open tiling is the
 -- identical number the full week returns. Measured: 631738 rows at 7, 28 and
 -- 56 slices and at one week. Slices are generated rather than counted because
 -- a DST week is 167 or 169 hours, and LEAST clamps the last end to p_end.
 -- Nothing is skipped, no timeout is extended, and the week's own certificate
 -- is still written only from the complete sum, below.
 v_bad:=0;
 FOR v_slice_start,v_slice_end IN
  SELECT s.a,LEAST(s.a+interval '3 hours',p_end)
  FROM generate_series(p_start,p_end-interval '1 microsecond',interval '3 hours') s(a) ORDER BY s.a
 LOOP
 v_slice:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_touched',p_union_id,v_slice_start,v_slice_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_touched',p_union_id,v_slice_start,v_slice_end));
 IF v_slice IS NOT NULL THEN
  v_bad:=v_bad+(v_slice->>'bad')::bigint;
 ELSE
 WITH touched AS MATERIALIZED (
  SELECT w.registration_id row_id,w.touched_tournament_id tournament_id
  FROM public.fn_union_pnl_touched_registrations(v_slice_start,v_slice_end,v_inv) w
 ), distinct_tournaments AS MATERIALIZED (
  SELECT DISTINCT tournament_id FROM touched
 ), union_tournaments AS MATERIALIZED (
  SELECT d.tournament_id FROM distinct_tournaments d
  WHERE (CASE WHEN v_inv THEN EXISTS(SELECT 1 FROM public.union_pnl_inventory_touches t WHERE t.source_name='tournaments'
   AND t.row_id=CASE WHEN d.tournament_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN d.tournament_id::uuid END
   AND t.row_id::text=d.tournament_id
   AND t.union_id=p_union_id::text) ELSE EXISTS(SELECT 1 FROM public.union_pnl_inventory_events t WHERE t.source_name='tournaments'
  AND t.row_id=CASE WHEN d.tournament_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN d.tournament_id::uuid END
  AND t.row_id::text=d.tournament_id
  AND COALESCE(t.after_row,t.before_row)->>'union_id'=p_union_id::text) END)
 ), union_touched AS MATERIALIZED (
  SELECT i.row_id FROM touched i WHERE i.tournament_id IN (SELECT tournament_id FROM union_tournaments)
 ), entries AS MATERIALIZED (
  -- the two receipt tests, read once per touched registration (column for
  -- column: a whole-row argument would detoast every receipt's snapshots)
  SELECT r.registration_id,
   bool_or(r.asset='chips' AND public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NOT NULL) has_entry,
   bool_or(r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NULL) has_other
  FROM public.tournament_participant_funding_receipts r
  WHERE r.registration_id IN (SELECT row_id FROM union_touched)
  GROUP BY r.registration_id
 ), unresolved_registrations AS MATERIALIZED (
  SELECT DISTINCT i.row_id FROM union_touched i LEFT JOIN entries e ON e.registration_id=i.row_id
  WHERE NOT COALESCE(e.has_entry,false) AND i.row_id<>ALL(v_open_resolved)
 ), satellite_owners AS MATERIALIZED (
  SELECT i.row_id,public.fn_union_pnl_satellite_seat_owner(i.row_id,NULL) owner
  FROM unresolved_registrations i
 ) SELECT count(*) INTO v_slice_bad FROM union_touched i LEFT JOIN entries e ON e.registration_id=i.row_id
 LEFT JOIN satellite_owners o ON o.row_id=i.row_id
 WHERE (NOT COALESCE(e.has_entry,false) AND i.row_id<>ALL(v_open_resolved)
   AND o.owner IS NULL)
  OR COALESCE(e.has_other,false);
  PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched',p_union_id,v_slice_start,v_slice_end,jsonb_build_object('bad',v_slice_bad));
  v_bad:=v_bad+v_slice_bad;
  -- One sub-range per visit, through the yield that already exists:
  -- fn_accounting_close_certify sets app.accounting_close_certified, which is
  -- what fn_accounting_close_warm_stop reads. The next visit resumes from the
  -- sub-ranges already certified above. No new setting, no new deadline.
  IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 END IF;
 END LOOP;
  IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad));
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_original_population_or_instrument_incomplete','count',v_bad)); END IF;
 -- An award must return to the original funding club; a changed credited
 -- wallet does not prove a new earning ownership agreement.
 -- The week's credits of this Union (its tournament snapshot's Union, its
 -- frame in the week) come from union_pnl_credit_touches once complete. The
 -- two whole-row resolutions (a whole-row value detoasts every snapshot of
 -- the credit) are asked only of a credit the entry test did not settle: the
 -- same conjunction, in an order the planner may not change.
 SELECT count(*) INTO v_bad FROM public.fn_union_pnl_week_union_credits(p_union_id,p_start,p_end,v_credit) w
 JOIN public.tournament_accounting_credit_receipts c ON c.id=w.credit_id
 WHERE CASE WHEN (cardinality(c.entry_receipt_ids)=0 OR EXISTS(SELECT 1 FROM unnest(c.entry_receipt_ids) original_id(receipt_id)
   LEFT JOIN public.tournament_participant_funding_receipts r ON r.id=original_id.receipt_id
   WHERE r.id IS NULL OR r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS DISTINCT FROM c.credited_club_id OR r.user_id IS DISTINCT FROM c.user_id))
  THEN NOT public.fn_union_pnl_award_owner_resolved(c,p_union_id,p_start,v_open_resolved)
   AND NOT public.fn_union_pnl_award_satellite_owner(c) ELSE false END;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_award_original_earning_owner_incomplete','count',v_bad)); END IF;
 v_eco:=public.fn_union_eco_terms_evidence(p_union_id,p_start,p_end);
 IF v_eco->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','eco_commercial_basis_incomplete','evidence',v_eco)); END IF;
 SELECT count(DISTINCT x->'terms') INTO v_bad FROM jsonb_array_elements(COALESCE(v_eco->'segments','[]')) x;
 IF v_bad<>1 THEN v_issues:=v_issues||jsonb_build_array('eco_intraweek_changed_terms_require_original_allocation'); END IF;
 v_terms_value:=v_eco#>'{segments,0,terms}';
 -- Validate every original bank/source leg even when the week has no rows.
 -- CHUNKED CLOSE WINDOWS (20261003): inside a chunked close the plan's
 -- two-hour windows are proved first, a few per attempt; until all are, the
 -- attempt stops warming (fn_accounting_union_earned_plan_advance is NULL,
 -- and this test passes, everywhere else).
 -- (THE WINDOWS GO FIRST, 20261012: the plan's windows are proved above,
 -- right after the opening boundary, before any step that can be re-proved.)
 PERFORM public.fn_accounting_union_earned_plan(p_union_id,p_start,p_end);
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF md5(pg_get_functiondef('smarter_private.weekly_hand_parts_witness(uuid,timestamptz,timestamptz,boolean)'::regprocedure)) IS DISTINCT FROM 'a101812df22c1dfb379ebc325bd7d6d0'
 OR md5(pg_get_functiondef('smarter_private.weekly_hand_parts_reduce(uuid,timestamptz,timestamptz,boolean)'::regprocedure)) IS DISTINCT FROM '97fc255997a2faeac593b5b1f5420d4c'
 OR md5(pg_get_functiondef('smarter_private.weekly_hand_parts_read(uuid,timestamptz,timestamptz,text,boolean)'::regprocedure)) IS DISTINCT FROM 'd427fd27d163ba72a7dc3cd50866163d'
 THEN RAISE EXCEPTION 'weekly_hand_parts_owner_changed';END IF;
 IF (SELECT count(*) FROM pg_proc WHERE oid IN('smarter_private.weekly_hand_parts_witness(uuid,timestamptz,timestamptz,boolean)'::regprocedure,'smarter_private.weekly_hand_parts_reduce(uuid,timestamptz,timestamptz,boolean)'::regprocedure,'smarter_private.weekly_hand_parts_read(uuid,timestamptz,timestamptz,text,boolean)'::regprocedure)
  AND proowner='postgres'::regrole AND NOT prosecdef AND provolatile='s' AND proacl::text='{postgres=X/postgres}' AND proconfig=ARRAY['search_path=pg_catalog, public, smarter_private']) IS DISTINCT FROM 3::bigint THEN RAISE EXCEPTION 'weekly_hand_parts_owner_authority_changed';END IF;
 v_hand_parts:=smarter_private.weekly_hand_parts_read(p_union_id,p_start,p_end,v_generation,v_cash);
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_clubs',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_clubs',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_clubs:=v_cert->'clubs'; v_cash_reconciled:=(v_cert->>'cash_reconciled')::boolean; v_rows:=(v_cert->>'rows')::bigint;
  v_cash_rake:=(v_cert->>'cash_rake')::numeric; v_hands:=(v_cert->>'hands')::bigint; v_accepted_rake:=(v_cert->>'accepted_rake')::numeric;
 ELSE
 WITH flows AS MATERIALIZED (SELECT * FROM jsonb_to_recordset(v_flows)
  AS f(ledger_id uuid,club_id uuid,user_id uuid,buyins numeric,cashouts numeric,kind text,valid boolean)),
 -- One read of the week's hands: each (club, player) delta total, and (kind 0)
 -- the hand count and accepted rake that used to cost two more reads.
 outcome_pass AS MATERIALIZED (
 SELECT kind,club_id,user_id,delta,hands,rake FROM jsonb_to_recordset(v_hand_parts)x(kind integer,club_id uuid,user_id uuid,delta numeric,hands bigint,rake numeric)
 UNION ALL SELECT original.* FROM LATERAL(

  SELECT x.kind,x.club_id,x.user_id,sum(x.delta) delta,count(*) hands,sum(x.rake) rake
  FROM (SELECT h.hand_accepted_rake accepted_rake,h.hand_participants participants
   FROM public.fn_union_pnl_week_hand_lines(p_union_id,p_start,p_end,v_cash) h
   -- with this Union's linked hands, through their link resolutions
   UNION ALL SELECT k.evidence->>'accepted_rake',k.evidence->'participants' FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k) o CROSS JOIN LATERAL (
   SELECT 0 kind,NULL::uuid club_id,NULL::uuid user_id,NULL::numeric delta,o.accepted_rake::numeric rake
   UNION ALL
   SELECT 1,(p->>'earning_club_id')::uuid,(p->>'user_id')::uuid,(p->>'observed_stack_delta')::numeric,NULL::numeric
   FROM jsonb_array_elements(COALESCE(o.participants,'[]')) p) x
  GROUP BY x.kind,x.club_id,x.user_id

 )original WHERE v_hand_parts IS NULL
 ), hand_players AS (SELECT club_id,user_id,delta FROM outcome_pass WHERE kind=1
  -- JACKPOT SHARES ON THE FELT (20260929): a Bad Beat Jackpot share credited
  -- to a seat after its hand committed is that player's cash result too.
  UNION ALL SELECT a.club_id,a.user_id,a.amount FROM public.fn_union_pnl_week_bbj_stack_awards(p_union_id,p_start,p_end) a), opening AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x GROUP BY 1),
 closing AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x GROUP BY 1),
 -- The canonical payout basis excludes retained Union-house rake. Gross
 -- original rake still belongs in the all-player P&L and bank reconciliation.
 rake AS MATERIALIZED (
  SELECT s.club_id,sum(s.rake_credit) generated,COALESCE(k.earned,0) earned,
   sum(s.rake_credit) FILTER(WHERE s.source_type='cash_rake_accrual') cash_rake,
   sum(s.rake_credit) FILTER(WHERE s.source_type='tournament_fee_accrual') tournament_rake
  FROM public.accounting_payable_earning_sources s
  LEFT JOIN (SELECT club_id,sum(payout) earned FROM public.fn_union_club_rake_basis(p_union_id,p_start,p_end) GROUP BY club_id) k ON k.club_id=s.club_id
  WHERE s.union_id=p_union_id AND s.earned_at>=p_start AND s.earned_at<p_end GROUP BY s.club_id,k.earned
 ),
 roster AS (
  SELECT DISTINCT (COALESCE(after_row,before_row)->>'club_id')::uuid club_id FROM public.union_pnl_inventory_events
   WHERE source_name='union_clubs' AND COALESCE(after_row,before_row)->>'union_id'=p_union_id::text AND observed_at<p_end
    AND (observed_at>=p_start OR row_id::text IN(SELECT x#>>'{row,id}' FROM jsonb_array_elements(COALESCE(v_open#>'{inventory,population,union_clubs}','[]')) x))
  UNION SELECT club_id FROM rake UNION SELECT club_id FROM flows UNION SELECT club_id FROM hand_players UNION SELECT club_id FROM opening UNION SELECT club_id FROM closing
 ), movement AS (SELECT club_id,sum(buyins) buyins,sum(cashouts) cashouts,
  sum(cashouts-buyins) FILTER(WHERE kind IN('cash_funding','cash_return','cash_late_settlement')) cash_flow,
  sum(buyins) FILTER(WHERE kind='cash_funding') cash_buyins,sum(cashouts) FILTER(WHERE kind='cash_return') cash_cashouts FROM flows GROUP BY club_id),
 hands AS (SELECT club_id,sum(delta) delta FROM hand_players GROUP BY club_id),
 people AS (SELECT club_id,count(DISTINCT user_id)::int players FROM(SELECT club_id,user_id FROM flows UNION SELECT club_id,user_id FROM hand_players
  UNION SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')||COALESCE(v_close->'holdings','[]')) x) q GROUP BY club_id),
 club_rows AS (
  SELECT r.club_id,COALESCE(m.buyins,0) buyins,COALESCE(m.cashouts,0) cashouts,COALESCE(m.cash_buyins,0) cash_buyins,COALESCE(m.cash_cashouts,0) cash_cashouts,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0) realized_net,COALESCE(o.amount,0) seated_start,COALESCE(c.amount,0) seated_end,
   COALESCE(o.cash,0) seated_start_cash,COALESCE(c.cash,0) seated_end_cash,
   COALESCE(c.amount,0)-COALESCE(o.amount,0) stack_delta,COALESCE(h.delta,0) cash_player_pnl,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)-COALESCE(h.delta,0) tournament_player_pnl,
   COALESCE(m.cash_flow,0)+COALESCE(c.cash,0)-COALESCE(o.cash,0)=COALESCE(h.delta,0) cash_reconciled,
   COALESCE(p.players,0) players,COALESCE(k.generated,0) rake_paid,COALESCE(k.earned,0) rake_earned,COALESCE(k.cash_rake,0) cash_rake,COALESCE(k.tournament_rake,0) tournament_rake,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)+COALESCE(k.generated,0) net
  FROM roster r LEFT JOIN movement m USING(club_id) LEFT JOIN opening o USING(club_id) LEFT JOIN closing c USING(club_id)
  LEFT JOIN hands h USING(club_id) LEFT JOIN people p USING(club_id) LEFT JOIN rake k USING(club_id)
  WHERE r.club_id IS NOT NULL
 ), player_results AS (
  SELECT club_id,user_id,sum(delta) delta FROM (
   SELECT club_id,user_id,cashouts-buyins delta FROM flows
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,-(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  ) amounts GROUP BY club_id,user_id
 ), wins AS(SELECT club_id,sum(greatest(delta,0)) winnings,sum(greatest(-delta,0)) losses FROM player_results GROUP BY club_id), complete AS (
  SELECT q.*,COALESCE(w.winnings,0) winnings,COALESCE(w.losses,0) losses,
   CASE v_terms_value->>'eco_base_mode'
    WHEN 'club_cash_profit' THEN rake_earned-cash_player_pnl
    WHEN 'net_invoice_position' THEN realized_net+stack_delta+rake_paid+rake_earned
    WHEN 'winnings_plus_rake' THEN realized_net+stack_delta+rake_paid
    WHEN 'winnings_only' THEN realized_net+stack_delta END eco_base
  FROM club_rows q LEFT JOIN wins w USING(club_id)
 ) SELECT COALESCE(jsonb_agg(to_jsonb(q)||jsonb_build_object('eco_amount',CASE WHEN v_terms_value->'eco_enabled'='true'::jsonb
  THEN round(-(v_terms_value->>'eco_rate')::numeric*eco_base,2) ELSE 0 END) ORDER BY club_id),'[]'),
  COALESCE(bool_and(cash_reconciled),true),count(*),COALESCE(sum(cash_rake),0),
  COALESCE((SELECT h.hands FROM outcome_pass h WHERE h.kind=0),0),(SELECT COALESCE(sum(h.rake),0) FROM outcome_pass h WHERE h.kind=0)
  INTO v_clubs,v_cash_reconciled,v_rows,v_cash_rake,v_hands,v_accepted_rake FROM complete q;
  IF v_hand_parts IS NOT NULL AND smarter_private.weekly_hand_parts_read(p_union_id,p_start,p_end,v_generation,v_cash) IS DISTINCT FROM v_hand_parts THEN
   RAISE EXCEPTION 'weekly_hand_parts_sources_changed_during_report';END IF;
  IF v_cash_reconciled AND (v_accepted_rake IS NOT DISTINCT FROM v_cash_rake OR v_accepted_rake-public.fn_union_pnl_week_rake_straddle(p_union_id,p_start,p_end) IS NOT DISTINCT FROM v_cash_rake) THEN
   PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_clubs',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  ELSE
   PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_clubs_problem',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  END IF;
 END IF;
 IF v_accepted_rake IS DISTINCT FROM v_cash_rake AND v_accepted_rake-public.fn_union_pnl_week_rake_straddle(p_union_id,p_start,p_end) IS DISTINCT FROM v_cash_rake THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_rake_does_not_match_original_earning_and_bank_basis'); END IF;
 IF NOT v_cash_reconciled THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_deltas_do_not_reconcile_original_flows_and_boundaries'); END IF;
 v_report:=jsonb_build_object('report_version',1,'status',CASE WHEN v_issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'basis_certified',v_issues='[]'::jsonb,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
  'issues',v_issues,'clubs',v_clubs,'opening_basis',v_open,'closing_basis',v_close,'eco_commercial_terms_evidence',v_eco,
  'accepted_cash_hands',v_hands,'accepted_cash_hands_resolved',v_resolved,'club_count',v_rows,'current_seats_used',false,'current_membership_used',false,
  'all_players_included',v_issues='[]'::jsonb,'tournament_basis','original_realized_settlement_deferred_while_open');
 IF v_memo_key IS NOT NULL THEN
  PERFORM set_config('app.union_pnl_evidence_memo',(COALESCE(NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb,'{}')
   ||jsonb_build_object(v_memo_key,v_report))::text,true);
 END IF;
 RETURN v_report;
END $function$

public.fn_union_pnl_first_inventory_oper.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_first_inventory_operation(p_source text, p_row_id uuid, p_projected boolean)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v text;
BEGIN
 IF p_projected AND p_source IN ('tournament_players','tournaments') THEN
  SELECT t.operation INTO v FROM public.union_pnl_inventory_touches t WHERE t.source_name=p_source AND t.row_id=p_row_id ORDER BY t.event_id LIMIT 1;
 ELSE
  SELECT e.operation INTO v FROM public.union_pnl_inventory_events e WHERE e.source_name=p_source AND e.row_id=p_row_id ORDER BY e.event_id LIMIT 1;
 END IF;
 RETURN v;
END $function$

public.fn_union_pnl_inventory_as_of(p_at.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_as_of(p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; book timestamptz; v_base timestamptz; v_projection jsonb; v_result jsonb;
BEGIN
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','blocked','reason','inventory_capture_missing'); END IF;
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() THEN
  RETURN jsonb_build_object('status','blocked','reason','closed_original_week_boundary_required'); END IF;
 IF p_at<=origin.captured_at THEN RETURN jsonb_build_object('status','blocked','reason','boundary_precedes_original_inventory_capture','capture_started_at',origin.captured_at); END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RETURN jsonb_build_object('status','blocked','reason','inventory_requires_fresh_read_committed_snapshot'); END IF;
 book:=public.fn_union_week_start(origin.captured_at);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
 -- Every writer that could precede p_at has committed (the locks above), so
 -- the result is final: one transaction computes it once.
 IF to_regclass('pg_temp.union_pnl_inventory_as_of_cache') IS NOT NULL THEN
  EXECUTE 'SELECT result FROM pg_temp.union_pnl_inventory_as_of_cache WHERE boundary=$1' INTO v_result USING p_at;
  IF v_result IS NOT NULL THEN RETURN v_result; END IF;
 END IF;
 -- VOLATILE intentionally obtains a fresh snapshot after the old-book writers
 -- have committed. A stable/snapshot reader could omit those committed events.
 SELECT c.boundary INTO v_base FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary<=p_at ORDER BY c.boundary DESC LIMIT 1;
 v_projection:=public.fn_union_pnl_inventory_population(v_base,p_at);
 v_result:=jsonb_build_object('status',CASE WHEN v_projection->'issues'='[]'::jsonb THEN 'observed' ELSE 'blocked' END,
  'inventory_version',1,'capture_started_at',origin.captured_at,'boundary',p_at,'population',v_projection->'population','issues',v_projection->'issues',
  'current_state_used',false,'financial_basis_certified',false,
  'coverage','Original active population and later captured transitions; monetary funding and obligation receipts must independently certify equity.');
 BEGIN
  IF to_regclass('pg_temp.union_pnl_inventory_as_of_cache') IS NULL THEN
   EXECUTE 'CREATE TEMP TABLE union_pnl_inventory_as_of_cache(boundary timestamptz PRIMARY KEY, result jsonb NOT NULL) ON COMMIT DROP';
  END IF;
  EXECUTE 'INSERT INTO pg_temp.union_pnl_inventory_as_of_cache(boundary,result) VALUES($1,$2) ON CONFLICT (boundary) DO NOTHING' USING p_at,v_result;
 EXCEPTION WHEN read_only_sql_transaction THEN NULL;
 END;
 RETURN v_result;
END $function$

public.fn_union_pnl_inventory_as_of_lega.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_as_of_legacy(p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; book timestamptz; population jsonb; gaps jsonb;
BEGIN
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','blocked','reason','inventory_capture_missing'); END IF;
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() THEN
  RETURN jsonb_build_object('status','blocked','reason','closed_original_week_boundary_required'); END IF;
 IF p_at<=origin.captured_at THEN RETURN jsonb_build_object('status','blocked','reason','boundary_precedes_original_inventory_capture','capture_started_at',origin.captured_at); END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RETURN jsonb_build_object('status','blocked','reason','inventory_requires_fresh_read_committed_snapshot'); END IF;
 book:=public.fn_union_week_start(origin.captured_at);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
 -- VOLATILE intentionally obtains a fresh snapshot after the old-book writers
 -- have committed. A stable/snapshot reader could omit those committed events.
 WITH history AS MATERIALIZED (
  SELECT e.*,row_number() OVER(PARTITION BY source_name,row_id ORDER BY event_id DESC) latest,
   first_value(operation) OVER(PARTITION BY source_name,row_id ORDER BY event_id) first_operation,
   row_number() OVER(PARTITION BY source_name,row_id ORDER BY event_id) ordinal,
   lag(after_row) OVER(PARTITION BY source_name,row_id ORDER BY event_id) prior_after
  FROM public.union_pnl_inventory_events e WHERE observed_at<p_at
 ), current_rows AS MATERIALIZED (
  SELECT source_name,row_id,event_id,after_row,first_operation FROM history WHERE latest=1 AND after_row IS NOT NULL
 ), active AS MATERIALIZED (
  SELECT * FROM current_rows r WHERE source_name='union_clubs'
   OR (source_name='tables' AND after_row->'tournament_id'='null'::jsonb)
   OR (source_name='table_seats' AND after_row->'left_at'='null'::jsonb)
   OR (source_name='tournaments' AND after_row->>'status' NOT IN ('COMPLETED','CANCELLED'))
   OR (source_name='tournament_players' AND EXISTS(SELECT 1 FROM current_rows t WHERE t.source_name='tournaments'
    AND t.row_id::text=r.after_row->>'tournament_id' AND t.after_row->>'status' NOT IN ('COMPLETED','CANCELLED')))
 ), grouped AS (
  SELECT source_name,jsonb_agg(jsonb_build_object('source_event_id',event_id,'row',after_row) ORDER BY row_id) rows FROM active GROUP BY source_name
 ) SELECT COALESCE((SELECT jsonb_object_agg(source_name,rows) FROM grouped),'{}'),
  COALESCE((SELECT jsonb_agg(jsonb_build_object('source_name',source_name,'row_id',row_id,'reason','active_row_original_population_missing') ORDER BY source_name,row_id)
   FROM active WHERE first_operation NOT IN ('baseline','INSERT')),'[]')
  ||COALESCE((SELECT jsonb_agg(jsonb_build_object('source_name',source_name,'row_id',row_id,'source_event_id',event_id,'reason','original_inventory_chain_disagrees') ORDER BY source_name,row_id,event_id)
   FROM history WHERE ordinal>1 AND prior_after IS DISTINCT FROM before_row),'[]') INTO population,gaps;
 RETURN jsonb_build_object('status',CASE WHEN gaps='[]'::jsonb THEN 'observed' ELSE 'blocked' END,
  'inventory_version',1,'capture_started_at',origin.captured_at,'boundary',p_at,'population',population,'issues',gaps,
  'current_state_used',false,'financial_basis_certified',false,
  'coverage','Original active population and later captured transitions; monetary funding and obligation receipts must independently certify equity.');
END $function$

public.fn_union_pnl_inventory_checkpoint.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_checkpoint_due()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; b timestamptz; v_sealed jsonb:='[]'; v_step jsonb;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','blocked','reason','inventory_capture_missing'); END IF;
 b:=public.fn_union_week_start(origin.captured_at);
 LOOP
  b:=public.fn_union_week_start(b+interval '8 days');
  EXIT WHEN b>clock_timestamp();
  IF NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary=b) THEN
   IF jsonb_array_length(v_sealed)>0 THEN
    RETURN jsonb_build_object('status','sealing','boundary',b,'progress',jsonb_build_object('stage','pending_boundary'),'sealed',v_sealed);
   END IF;
   -- One bounded seal operation per original close transaction.
   IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')='on' THEN
    v_step:=public.fn_union_pnl_inventory_seal_advance(b,false);
   ELSE
    v_step:=public.fn_union_pnl_inventory_checkpoint_seal(b,false);
   END IF;
   IF v_step->>'status'='sealing' THEN
    RETURN jsonb_build_object('status','sealing','boundary',b,'progress',v_step,'sealed',v_sealed);
   END IF;
   IF v_step->>'status' NOT IN ('sealed','already_sealed') THEN
    RAISE EXCEPTION 'inventory_seal_receipt_invalid' USING ERRCODE='55000'; END IF;
   v_sealed:=jsonb_build_array(v_step);
  END IF;
 END LOOP;
 RETURN jsonb_build_object('status','ready','sealed',v_sealed);
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_checkpoint_seal(p_at timestamp with time zone, p_verify_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; book timestamptz; v_base timestamptz;
 v_prior public.union_pnl_inventory_checkpoints%ROWTYPE; v_rows bigint; v_issues bigint; v_rows_md5 text; v_issues_md5 text;
 v_max bigint; v_projection jsonb; v_legacy jsonb; v_started timestamptz:=clock_timestamp(); v_ms bigint;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'inventory_capture_missing' USING ERRCODE='55000'; END IF;
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() OR p_at<=origin.captured_at THEN
  RAISE EXCEPTION 'closed_original_week_boundary_required' USING ERRCODE='22023'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'inventory_requires_fresh_read_committed_snapshot' USING ERRCODE='25000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory-checkpoint',0));
 SELECT * INTO v_prior FROM public.union_pnl_inventory_checkpoints WHERE boundary=p_at;
 IF FOUND THEN
  RETURN jsonb_build_object('status','already_sealed','boundary',p_at,'base_boundary',v_prior.base_boundary,'row_count',v_prior.row_count,
   'issue_count',v_prior.issue_count,'rows_md5',v_prior.rows_md5,'result_md5',v_prior.result_md5,'legacy_verified',v_prior.legacy_verified);
 END IF;
 book:=public.fn_union_week_start(origin.captured_at);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
 SELECT c.boundary INTO v_base FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary<p_at ORDER BY c.boundary DESC LIMIT 1;
 IF true AND public.fn_union_pnl_inventory_snapshot_restore(p_at,v_base) THEN
  SELECT h.row_count,h.issue_count,h.rows_md5,h.issues_md5,h.max_event_id INTO v_rows,v_issues,v_rows_md5,v_issues_md5,v_max FROM public.union_pnl_inventory_seal_snapshot_head h WHERE h.boundary=p_at;
 ELSE
 IF to_regclass('pg_temp.union_pnl_inventory_seal') IS NOT NULL THEN EXECUTE 'DROP TABLE pg_temp.union_pnl_inventory_seal'; END IF;
 EXECUTE 'CREATE TEMP TABLE union_pnl_inventory_seal ON COMMIT DROP AS SELECT * FROM public.fn_union_pnl_inventory_state($1,$2)' USING v_base,p_at;
 EXECUTE $q$SELECT count(*) FILTER(WHERE o_kind='row'),count(*) FILTER(WHERE o_kind='issue'),
   NULL::text,
   md5(COALESCE(string_agg(concat_ws('|',o_source_name,o_row_id,o_event_id),E'\n'
    ORDER BY o_source_name,o_row_id,o_event_id) FILTER(WHERE o_kind='issue'),'')),
   max(o_event_id) FILTER(WHERE o_kind='row')
  FROM pg_temp.union_pnl_inventory_seal$q$ INTO v_rows,v_issues,v_rows_md5,v_issues_md5,v_max;
 -- THE ROWS HASH IS TAKEN BUCKET BY BUCKET (2026-10-12): one string of every
 -- row passed the 1 GB limit of a value at ~3M rows (54000). Each bucket (one
 -- source, the first two hex digits of row_id) is hashed in row order, and the
 -- bucket hashes are hashed in the same order.
  EXECUTE $q$SELECT md5(COALESCE(string_agg(x.h,E'\n' ORDER BY x.sn,x.b),'')) FROM (SELECT o_source_name sn,left(o_row_id::text,2) b,
    md5(string_agg(concat_ws('|',o_source_name,o_row_id,o_event_id,o_first_operation,COALESCE(o_after_row::text,'~')),E'\n'
     ORDER BY o_source_name,o_row_id)) h
    FROM pg_temp.union_pnl_inventory_seal WHERE o_kind='row' GROUP BY 1,2) x$q$ INTO v_rows_md5;
 IF true THEN PERFORM public.fn_union_pnl_inventory_snapshot_save(p_at,v_base,v_rows,v_issues,v_rows_md5,v_issues_md5,v_max); END IF;
 END IF;
 -- THE FINAL COPY IS A BOUNDED COMMITTED PAGE (20261012).
 IF NOT public.fn_union_pnl_inventory_seal_write_page(p_at,v_base) THEN
  EXECUTE 'DROP VIEW pg_temp.union_pnl_inventory_seal';
  RETURN jsonb_build_object('status','sealing','boundary',p_at,'base_boundary',v_base,'stage','committed_build_page');
 END IF;
 EXECUTE 'DROP VIEW pg_temp.union_pnl_inventory_seal';
 -- Read the result back from the rows just written, exactly as a later reader will.
 v_projection:=public.fn_union_pnl_inventory_build_population(p_at,p_at);
 IF p_verify_legacy THEN
  v_legacy:=public.fn_union_pnl_inventory_as_of_legacy(p_at);
  IF v_legacy->'population' IS DISTINCT FROM v_projection->'population' OR v_legacy->'issues' IS DISTINCT FROM v_projection->'issues' THEN
   RAISE EXCEPTION 'inventory_checkpoint_disagrees_with_legacy_reader' USING ERRCODE='55000',
    DETAIL=jsonb_build_object('boundary',p_at,'legacy_md5',md5(jsonb_build_object('population',v_legacy->'population','issues',v_legacy->'issues')::text),
     'checkpoint_md5',md5(v_projection::text))::text;
  END IF;
 END IF;
 v_ms:=(extract(epoch FROM clock_timestamp()-v_started)*1000)::bigint;
 INSERT INTO public.union_pnl_inventory_checkpoints(boundary,base_boundary,max_event_id,row_count,issue_count,rows_md5,issues_md5,result_md5,legacy_verified,seal_ms)
 VALUES(p_at,v_base,v_max,v_rows,v_issues,v_rows_md5,v_issues_md5,md5(v_projection::text),p_verify_legacy IS TRUE,v_ms);
 RETURN jsonb_build_object('status','sealed','boundary',p_at,'base_boundary',v_base,'max_event_id',v_max,'row_count',v_rows,'issue_count',v_issues,
  'rows_md5',v_rows_md5,'result_md5',md5(v_projection::text),'legacy_verified',p_verify_legacy IS TRUE,
  'result_issues',jsonb_array_length(v_projection->'issues'),'seal_ms',v_ms);
END $function$

public.fn_union_pnl_inventory_seal_advan.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_seal_advance(p_at timestamp with time zone, p_verify boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
-- Seals a closed week's original inventory six hours at a time (see the
-- migration header); returns status 'sealing' while layers remain.
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; book timestamptz; v_base timestamptz; v_prior public.union_pnl_inventory_checkpoints%ROWTYPE;
 g record; began timestamptz:=clock_timestamp(); t0 timestamptz; done_any boolean:=false; n_layers int; n_done int;
 v_rows bigint; v_issues bigint; v_rows_md5 text; v_issues_md5 text; v_max bigint; v_projection jsonb; v_ms bigint; v_lr bigint; v_li bigint;
 v_wal0 pg_lsn:=pg_current_wal_insert_lsn(); v_pages int; c_kind text; c_source text; c_row uuid; c_event bigint;
BEGIN
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'inventory_capture_missing' USING ERRCODE='55000'; END IF;
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() OR p_at<=origin.captured_at THEN
  RAISE EXCEPTION 'closed_original_week_boundary_required' USING ERRCODE='22023'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'inventory_requires_fresh_read_committed_snapshot' USING ERRCODE='25000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory-checkpoint',0));
 SELECT * INTO v_prior FROM public.union_pnl_inventory_checkpoints WHERE boundary=p_at;
 IF FOUND AND NOT p_verify THEN
  RETURN jsonb_build_object('status','already_sealed','boundary',p_at,'base_boundary',v_prior.base_boundary,'row_count',v_prior.row_count,
   'issue_count',v_prior.issue_count,'rows_md5',v_prior.rows_md5,'result_md5',v_prior.result_md5,'legacy_verified',v_prior.legacy_verified);
 END IF;
 IF p_verify AND NOT FOUND THEN RAISE EXCEPTION 'inventory_verify_needs_a_sealed_week' USING ERRCODE='22023'; END IF;
 book:=public.fn_union_week_start(origin.captured_at);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
 SELECT c.boundary INTO v_base FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary<p_at ORDER BY c.boundary DESC LIMIT 1;
 -- A week with no base seals in one go, as before.
 IF v_base IS NULL THEN
  IF p_verify THEN RAISE EXCEPTION 'inventory_verify_needs_a_base' USING ERRCODE='22023'; END IF;
  RETURN public.fn_union_pnl_inventory_checkpoint_seal(p_at,false);
 END IF;
 -- Staging holds one week at a time; layers made for another base are stale.
 IF NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_layers l WHERE l.boundary=p_at)
  OR EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_layers l WHERE l.boundary=p_at AND l.base_boundary IS DISTINCT FROM v_base) THEN
  TRUNCATE public.union_pnl_inventory_seal_layers, public.union_pnl_inventory_seal_layer_rows, public.union_pnl_inventory_seal_layer_issues;
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS _inv_layer(o_kind text,o_source_name text,o_row_id uuid,o_event_id bigint,o_first_operation text,o_after_row jsonb) ON COMMIT DROP;
 SELECT count(*) INTO n_layers FROM generate_series(v_base,p_at-interval '1 microsecond',interval '6 hours') s;
 FOR g IN SELECT s AS layer_start,LEAST(s+interval '6 hours',p_at) AS layer_end
   FROM generate_series(v_base,p_at-interval '1 microsecond',interval '6 hours') s ORDER BY 1 LOOP
  CONTINUE WHEN EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_layers l WHERE l.boundary=p_at AND l.layer_end=g.layer_end);
  IF done_any AND clock_timestamp()>began+interval '90 seconds' THEN
   SELECT count(*) INTO n_done FROM public.union_pnl_inventory_seal_layers l WHERE l.boundary=p_at;
   RETURN jsonb_build_object('status','sealing','boundary',p_at,'base_boundary',v_base,'layers',n_layers,'layers_done',n_done);
  END IF;
  t0:=clock_timestamp();
  TRUNCATE pg_temp._inv_layer;
  INSERT INTO pg_temp._inv_layer SELECT * FROM public.fn_union_pnl_inventory_layer_state(v_base,p_at,g.layer_start,g.layer_end);
  INSERT INTO public.union_pnl_inventory_seal_layer_rows(boundary,source_name,row_id,layer_end,latest_event_id,first_operation,after_row)
   SELECT p_at,o_source_name,o_row_id,g.layer_end,o_event_id,o_first_operation,o_after_row FROM pg_temp._inv_layer WHERE o_kind='row';
  GET DIAGNOSTICS v_lr=ROW_COUNT;
  INSERT INTO public.union_pnl_inventory_seal_layer_issues(boundary,source_name,row_id,layer_end,event_id)
   SELECT p_at,o_source_name,o_row_id,g.layer_end,o_event_id FROM pg_temp._inv_layer WHERE o_kind='issue';
  GET DIAGNOSTICS v_li=ROW_COUNT;
  INSERT INTO public.union_pnl_inventory_seal_layers(boundary,layer_end,layer_start,base_boundary,row_count,issue_count,layer_ms)
  VALUES(p_at,g.layer_end,g.layer_start,v_base,v_lr,v_li,(extract(epoch FROM clock_timestamp()-t0)*1000)::bigint);
  done_any:=true;
 END LOOP;
 IF done_any AND clock_timestamp()>began+interval '60 seconds' THEN
  RETURN jsonb_build_object('status','sealing','boundary',p_at,'base_boundary',v_base,'layers',n_layers,'layers_done',n_layers);
 END IF;
 -- The week: base rows no layer touched, and each touched row as of its
 -- latest layer; issues likewise.
 IF NOT p_verify AND public.fn_union_pnl_inventory_snapshot_restore(p_at,v_base) THEN
  SELECT h.row_count,h.issue_count,h.rows_md5,h.issues_md5,h.max_event_id INTO v_rows,v_issues,v_rows_md5,v_issues_md5,v_max FROM public.union_pnl_inventory_seal_snapshot_head h WHERE h.boundary=p_at;
 ELSE
 IF to_regclass('pg_temp.union_pnl_inventory_seal') IS NOT NULL THEN EXECUTE 'DROP TABLE pg_temp.union_pnl_inventory_seal'; END IF;
 CREATE TEMP TABLE union_pnl_inventory_seal ON COMMIT DROP AS
  WITH lt AS MATERIALIZED (SELECT DISTINCT ON (l.source_name,l.row_id) l.source_name sn,l.row_id rid,l.layer_end,l.latest_event_id eid,l.first_operation fop,l.after_row
    FROM public.union_pnl_inventory_seal_layer_rows l WHERE l.boundary=p_at ORDER BY l.source_name,l.row_id,l.layer_end DESC)
  SELECT 'row'::text o_kind,lt.sn o_source_name,lt.rid o_row_id,lt.eid o_event_id,lt.fop o_first_operation,lt.after_row o_after_row FROM lt
  UNION ALL
  SELECT 'row',r.source_name,r.row_id,r.latest_event_id,r.first_operation,r.after_row FROM public.union_pnl_inventory_published_rows r
   WHERE r.boundary=v_base AND NOT EXISTS(SELECT 1 FROM lt WHERE lt.sn=r.source_name AND lt.rid=r.row_id)
  UNION ALL
  SELECT 'issue',li.source_name,li.row_id,li.event_id,NULL::text,NULL::jsonb FROM lt JOIN public.union_pnl_inventory_seal_layer_issues li
   ON li.boundary=p_at AND li.layer_end=lt.layer_end AND li.source_name=lt.sn AND li.row_id=lt.rid
  UNION ALL
  SELECT 'issue',ci.source_name,ci.row_id,ci.event_id,NULL,NULL FROM public.union_pnl_inventory_published_issues ci
   WHERE ci.boundary=v_base AND NOT EXISTS(SELECT 1 FROM lt WHERE lt.sn=ci.source_name AND lt.rid=ci.row_id);
 -- From here on, exactly fn_union_pnl_inventory_checkpoint_seal.
 EXECUTE $q$SELECT count(*) FILTER(WHERE o_kind='row'),count(*) FILTER(WHERE o_kind='issue'),
   NULL::text,
   md5(COALESCE(string_agg(concat_ws('|',o_source_name,o_row_id,o_event_id),E'\n'
    ORDER BY o_source_name,o_row_id,o_event_id) FILTER(WHERE o_kind='issue'),'')),
   max(o_event_id) FILTER(WHERE o_kind='row')
  FROM pg_temp.union_pnl_inventory_seal$q$ INTO v_rows,v_issues,v_rows_md5,v_issues_md5,v_max;
 -- THE ROWS HASH IS TAKEN BUCKET BY BUCKET (2026-10-12): one string of every
 -- row passed the 1 GB limit of a value at ~3M rows (54000). Each bucket (one
 -- source, the first two hex digits of row_id) is hashed in row order, and the
 -- bucket hashes are hashed in the same order.
 -- Weeks up to 2026-10-05 were sealed whole; a verify of one recomputes that hash.
 IF p_verify AND p_at<='2026-10-05 07:00:00+00'::timestamptz THEN
  EXECUTE $q$SELECT md5(COALESCE(string_agg(concat_ws('|',o_source_name,o_row_id,o_event_id,o_first_operation,COALESCE(o_after_row::text,'~')),E'\n'
    ORDER BY o_source_name,o_row_id),'')) FROM pg_temp.union_pnl_inventory_seal WHERE o_kind='row'$q$ INTO v_rows_md5;
 ELSE
  EXECUTE $q$SELECT md5(COALESCE(string_agg(x.h,E'\n' ORDER BY x.sn,x.b),'')) FROM (SELECT o_source_name sn,left(o_row_id::text,2) b,
    md5(string_agg(concat_ws('|',o_source_name,o_row_id,o_event_id,o_first_operation,COALESCE(o_after_row::text,'~')),E'\n'
     ORDER BY o_source_name,o_row_id)) h
    FROM pg_temp.union_pnl_inventory_seal WHERE o_kind='row' GROUP BY 1,2) x$q$ INTO v_rows_md5;
 END IF;
 IF NOT p_verify THEN PERFORM public.fn_union_pnl_inventory_snapshot_save(p_at,v_base,v_rows,v_issues,v_rows_md5,v_issues_md5,v_max); END IF;
 END IF;
 IF p_verify THEN
  EXECUTE 'DROP TABLE pg_temp.union_pnl_inventory_seal';
  RETURN jsonb_build_object('status',CASE WHEN v_rows=v_prior.row_count AND v_issues=v_prior.issue_count AND v_rows_md5=v_prior.rows_md5
     AND v_issues_md5=v_prior.issues_md5 AND v_max IS NOT DISTINCT FROM v_prior.max_event_id THEN 'verified' ELSE 'differs' END,
   'boundary',p_at,'base_boundary',v_base,'layers',n_layers,'row_count',v_rows,'issue_count',v_issues,'rows_md5',v_rows_md5,'issues_md5',v_issues_md5,'max_event_id',v_max,
   'sealed',jsonb_build_object('row_count',v_prior.row_count,'issue_count',v_prior.issue_count,'rows_md5',v_prior.rows_md5,'issues_md5',v_prior.issues_md5,'max_event_id',v_prior.max_event_id));
 END IF;
 -- THE FINAL COPY IS A BOUNDED COMMITTED PAGE (20261012).
 IF NOT public.fn_union_pnl_inventory_seal_write_page(p_at,v_base) THEN
  -- SEVERAL BOUNDED PAGES A TICK, INSIDE A WAL SPAN (20261019102410). One
  -- page (~17,000 rows, ~14.5 MB of WAL, ~0.7 s) per five-minute tick put the
  -- 4.52M-row week of 2026-10-19 about 21 hours from its close. Keep writing
  -- pages while rows remain past the durable cursor, until 384 MB of WAL has
  -- been written since this call began (a quarter of Realtime's 1.5 GB slot
  -- lag cutoff), 45 s have passed, or 64 pages are written. Publication still
  -- waits for a later tick, after the final page committed.
  v_pages:=1;
  LOOP
   EXIT WHEN v_pages>=64 OR clock_timestamp()>began+interval '45 seconds'
    OR pg_wal_lsn_diff(pg_current_wal_insert_lsn(),v_wal0)>=402653184;
   SELECT b.last_kind,b.last_source,b.last_row,b.last_event INTO c_kind,c_source,c_row,c_event
    FROM public.union_pnl_inventory_seal_builds b WHERE b.boundary=p_at;
   EXIT WHEN c_kind IS NULL OR NOT EXISTS(SELECT 1 FROM pg_temp.union_pnl_inventory_seal s
    WHERE (s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id)>(c_kind,c_source,c_row,c_event));
   EXIT WHEN public.fn_union_pnl_inventory_seal_write_page(p_at,v_base);
   v_pages:=v_pages+1;
  END LOOP;
  EXECUTE 'DROP VIEW pg_temp.union_pnl_inventory_seal';
  RETURN jsonb_build_object('status','sealing','boundary',p_at,'base_boundary',v_base,'stage','committed_build_page','pages',v_pages);
 END IF;
 EXECUTE 'DROP VIEW pg_temp.union_pnl_inventory_seal';
 v_projection:=public.fn_union_pnl_inventory_build_population(p_at,p_at);
 SELECT COALESCE(sum(l.layer_ms),0)+(extract(epoch FROM clock_timestamp()-began)*1000)::bigint INTO v_ms FROM public.union_pnl_inventory_seal_layers l WHERE l.boundary=p_at;
 INSERT INTO public.union_pnl_inventory_checkpoints(boundary,base_boundary,max_event_id,row_count,issue_count,rows_md5,issues_md5,result_md5,legacy_verified,seal_ms)
 VALUES(p_at,v_base,v_max,v_rows,v_issues,v_rows_md5,v_issues_md5,md5(v_projection::text),false,v_ms);
 RETURN jsonb_build_object('status','sealed','boundary',p_at,'base_boundary',v_base,'max_event_id',v_max,'row_count',v_rows,'issue_count',v_issues,
  'rows_md5',v_rows_md5,'result_md5',md5(v_projection::text),'legacy_verified',false,'layers',n_layers,
  'result_issues',jsonb_array_length(v_projection->'issues'),'seal_ms',v_ms);
END $function$

public.fn_union_pnl_inventory_seal_write.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_seal_write_page(p_at timestamp with time zone, p_base timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_build public.union_pnl_inventory_seal_builds%ROWTYPE; v_n bigint;
 v_head record;v_rows bigint;v_issues bigint;v_max bigint;v_rows_md5 text;v_issues_md5 text;v_diff bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory-checkpoint',0));
 IF EXISTS(SELECT 1 FROM public.union_pnl_inventory_checkpoints WHERE boundary=p_at) THEN
  RAISE EXCEPTION 'inventory_build_boundary_already_published' USING ERRCODE='55000'; END IF;
 INSERT INTO public.union_pnl_inventory_seal_builds(boundary,base_boundary)
 VALUES(p_at,p_base) ON CONFLICT(boundary) DO NOTHING;
 SELECT * INTO STRICT v_build FROM public.union_pnl_inventory_seal_builds WHERE boundary=p_at;
 IF v_build.base_boundary IS DISTINCT FROM p_base THEN
  RAISE EXCEPTION 'inventory_build_base_changed' USING ERRCODE='55000'; END IF;
 -- Both cardinality and encoded volume are bounded before any logged row is written.
 -- No last-step copy: these private logged rows become the checkpoint's storage.
 DROP TABLE IF EXISTS pg_temp._inv_write_page;
 CREATE TEMP TABLE _inv_write_page ON COMMIT DROP AS
 WITH candidates AS MATERIALIZED (
  SELECT s.*,512+4*GREATEST(COALESCE(pg_column_size(s.o_after_row),0),COALESCE(octet_length(s.o_after_row::text),0))::bigint
   +octet_length(s.o_source_name)+COALESCE(octet_length(s.o_first_operation),0) cost
  FROM pg_temp.union_pnl_inventory_seal s
  WHERE (v_build.last_kind IS NULL OR (s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id)>(v_build.last_kind,v_build.last_source,v_build.last_row,v_build.last_event))
  AND ((s.o_kind='row' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_rows b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id))
   OR (s.o_kind='issue' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_issues b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id AND b.event_id=s.o_event_id)))
  ORDER BY s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id LIMIT 32768
 ), budgeted AS (
  SELECT c.*,sum(cost) OVER(ORDER BY o_kind,o_source_name,o_row_id,o_event_id ROWS UNBOUNDED PRECEDING) used
  FROM candidates c
 ) SELECT * FROM budgeted WHERE used<=33554432;
 SELECT count(*) INTO v_n FROM pg_temp._inv_write_page;
 IF v_n>0 THEN
  IF v_build.ready THEN RAISE EXCEPTION 'inventory_ready_build_has_missing_rows' USING ERRCODE='55000'; END IF;
  INSERT INTO public.union_pnl_inventory_seal_build_rows
   SELECT p_at,o_source_name,o_row_id,o_event_id,o_first_operation,o_after_row FROM pg_temp._inv_write_page WHERE o_kind='row';
  INSERT INTO public.union_pnl_inventory_seal_build_issues
   SELECT p_at,o_source_name,o_row_id,o_event_id FROM pg_temp._inv_write_page WHERE o_kind='issue';
  UPDATE public.union_pnl_inventory_seal_builds b SET last_kind=p.o_kind,last_source=p.o_source_name,last_row=p.o_row_id,last_event=p.o_event_id
   FROM (SELECT * FROM pg_temp._inv_write_page ORDER BY o_kind DESC,o_source_name DESC,o_row_id DESC,o_event_id DESC LIMIT 1) p
   WHERE b.boundary=p_at;
  -- Publication always uses a separate tick after the final write page committed.
  RETURN false;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.union_pnl_inventory_seal s
  WHERE (v_build.last_kind IS NULL OR (s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id)>(v_build.last_kind,v_build.last_source,v_build.last_row,v_build.last_event))
   AND (
  (s.o_kind='row' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_rows b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id))
   OR (s.o_kind='issue' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_issues b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id AND b.event_id=s.o_event_id)))) THEN
  RAISE EXCEPTION 'inventory_build_row_exceeds_bounded_page' USING ERRCODE='54000'; END IF;
 -- Independently prove the durable set, BUCKET BY BUCKET (20261019151632).
 -- The 4.52M-row week of 2026-10-19 could not publish: one EXCEPT ALL of the
 -- whole cache against the whole build, both ways, ran past 290 s on
 -- production, past job 272's 240 s tick, so the publishing tick was
 -- cancelled every time. Each side is now read ONCE into per-bucket counts
 -- and hashes (one source, the first two hex digits of row_id, the same
 -- buckets the rows hash already uses), and the two bucket sets must be
 -- identical: a missing, extra, duplicated or changed row or issue changes its
 -- bucket's count or hash. The build's own buckets then give the rows hash that
 -- must equal the original assembly's, as before.
 DROP TABLE IF EXISTS pg_temp._inv_build_buckets;
 CREATE TEMP TABLE _inv_build_buckets ON COMMIT DROP AS
  SELECT 'row'::text k,source_name sn,left(row_id::text,2) b,count(*) n,max(latest_event_id) mx,
   md5(string_agg(concat_ws('|',source_name,row_id,latest_event_id,first_operation,COALESCE(after_row::text,'~')),E'\n'
    ORDER BY source_name,row_id,latest_event_id)) h
  FROM public.union_pnl_inventory_seal_build_rows WHERE boundary=p_at GROUP BY 2,3
  UNION ALL
  SELECT 'issue',source_name,left(row_id::text,2),count(*),NULL::bigint,
   md5(string_agg(concat_ws('|',source_name,row_id,event_id),E'\n' ORDER BY source_name,row_id,event_id))
  FROM public.union_pnl_inventory_seal_build_issues WHERE boundary=p_at GROUP BY 2,3;
 DROP TABLE IF EXISTS pg_temp._inv_cache_buckets;
 CREATE TEMP TABLE _inv_cache_buckets ON COMMIT DROP AS
  SELECT s.o_kind k,s.o_source_name sn,left(s.o_row_id::text,2) b,count(*) n,
   md5(string_agg(CASE WHEN s.o_kind='row'
     THEN concat_ws('|',s.o_source_name,s.o_row_id,s.o_event_id,s.o_first_operation,COALESCE(s.o_after_row::text,'~'))
     ELSE concat_ws('|',s.o_source_name,s.o_row_id,s.o_event_id) END,E'\n'
    ORDER BY s.o_source_name,s.o_row_id,s.o_event_id)) h
  FROM pg_temp.union_pnl_inventory_seal s GROUP BY 1,2,3;
 SELECT count(*) INTO v_diff FROM pg_temp._inv_build_buckets x FULL JOIN pg_temp._inv_cache_buckets c
  ON c.k=x.k AND c.sn=x.sn AND c.b=x.b
  WHERE x.k IS NULL OR c.k IS NULL OR x.n IS DISTINCT FROM c.n OR x.h IS DISTINCT FROM c.h
   OR c.k NOT IN ('row','issue');
 IF v_diff>0 THEN RAISE EXCEPTION 'inventory_build_disagrees_with_assembled_source' USING ERRCODE='55000'; END IF;
 -- Independently checksum the durable rows; a cache value alone cannot certify them.
 SELECT * INTO STRICT v_head FROM public.union_pnl_inventory_seal_snapshot_head WHERE boundary=p_at;
 SELECT COALESCE(sum(n),0),max(mx),md5(COALESCE(string_agg(h,E'\n' ORDER BY sn,b),''))
  INTO v_rows,v_max,v_rows_md5 FROM pg_temp._inv_build_buckets WHERE k='row';
 SELECT count(*),md5(COALESCE(string_agg(concat_ws('|',source_name,row_id,event_id),E'\n'
   ORDER BY source_name,row_id,event_id),''))
 INTO v_issues,v_issues_md5 FROM public.union_pnl_inventory_seal_build_issues WHERE boundary=p_at;
 IF (v_rows,v_issues,v_rows_md5,v_issues_md5,v_max)
  IS DISTINCT FROM (v_head.row_count,v_head.issue_count,v_head.rows_md5,v_head.issues_md5,v_head.max_event_id) THEN
  RAISE EXCEPTION 'inventory_build_checksum_disagrees_with_original_source' USING ERRCODE='55000'; END IF;

 IF NOT v_build.ready THEN UPDATE public.union_pnl_inventory_seal_builds SET ready=true WHERE boundary=p_at; END IF;
 RETURN true;
END $function$

public.fn_union_pnl_inventory_snapshot_r.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_snapshot_restore(p_at timestamp with time zone, p_base timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE h public.union_pnl_inventory_seal_snapshot_head%ROWTYPE;
BEGIN
 SELECT * INTO h FROM public.union_pnl_inventory_seal_snapshot_head WHERE boundary=p_at;
 IF NOT FOUND THEN RETURN false; END IF;
 IF h.base_boundary IS DISTINCT FROM p_base THEN
  RAISE EXCEPTION 'inventory_snapshot_base_changed' USING ERRCODE='55000'; END IF;
 EXECUTE format('CREATE TEMP VIEW union_pnl_inventory_seal AS SELECT o_kind,o_source_name,o_row_id,o_event_id,o_first_operation,o_after_row FROM public.union_pnl_inventory_seal_snapshot WHERE boundary=%L::timestamptz',p_at);
 RETURN true;
END $function$

public.fn_union_pnl_inventory_snapshot_s.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_snapshot_save(p_at timestamp with time zone, p_base timestamp with time zone, p_rows bigint, p_issues bigint, p_rows_md5 text, p_issues_md5 text, p_max bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 TRUNCATE public.union_pnl_inventory_seal_snapshot_head,public.union_pnl_inventory_seal_snapshot;
 INSERT INTO public.union_pnl_inventory_seal_snapshot
  SELECT p_at,s.* FROM pg_temp.union_pnl_inventory_seal s;
 INSERT INTO public.union_pnl_inventory_seal_snapshot_head VALUES(p_at,p_base,p_rows,p_issues,p_rows_md5,p_issues_md5,p_max);
 EXECUTE 'DROP TABLE pg_temp.union_pnl_inventory_seal';
 IF NOT public.fn_union_pnl_inventory_snapshot_restore(p_at,p_base) THEN
  RAISE EXCEPTION 'inventory_snapshot_readback_missing' USING ERRCODE='55000'; END IF;
END $function$

public.fn_union_pnl_qualified_clubs(p_un.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_qualified_clubs(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE proof jsonb;
BEGIN
 proof:=public.fn_union_pnl_evidence_report(p_union_id,p_start,p_end);
 IF proof->'report_version' IS DISTINCT FROM '1'::jsonb OR proof->>'status' IS DISTINCT FROM 'ready'
  OR proof->'basis_certified' IS DISTINCT FROM 'true'::jsonb OR proof->'issues' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'union_pnl_basis_uncertified' USING ERRCODE='55000',DETAIL=COALESCE((proof->'issues')::text,'missing proof');
 END IF;
 RETURN proof;
END $function$

public.fn_union_settlement_cascade(p_uni.def:
CREATE OR REPLACE FUNCTION public.fn_union_settlement_cascade(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_preparation jsonb; v_credit_club record;
  v_from timestamptz := COALESCE(p_period_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_period_end,   public.fn_union_week_start(now()));
  v_r1 jsonb; v_r2 jsonb; v_r3 jsonb; v_eco jsonb; v_inv jsonb;
  v_floor timestamptz;
  v_club_statements jsonb; v_previous_validated text;
  v_sqlstate text; v_msg text; v_detail text; v_context text;
  v_pending jsonb; v_posted record; v_quality jsonb;
  -- CHUNKED CLOSE (20261003): set by job 272's tick; see
  -- fn_process_weekly_accounting_scope. Off, this function is unchanged.
  v_chunked boolean := COALESCE(current_setting('app.weekly_accounting_chunked', true), '') = 'on';

BEGIN
  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;

  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF public.fn_ca_launch_accounting_waived('union',p_union_id,v_to) THEN
    RETURN jsonb_build_object('success',true,'waived',true,'paid',false,'reason','owner_directed_launch_waiver','union_id',p_union_id,'period_start',v_from,'period_end',v_to);
  END IF;
  -- THE FLOOR, checked before anything moves. Round 1 has always honoured it;
  -- nothing above round 1 did, so three further rounds ran on a floored week.
  SELECT f.earliest_period_start INTO v_floor
    FROM union_settlement_floor f WHERE f.union_id = p_union_id;

  IF v_floor IS NOT NULL AND v_from < v_floor THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'before_settlement_floor',
      'period_start', v_from, 'period_end', v_to,
      'settlement_floor', v_floor,
      'note', 'This period is below the union settlement floor and must not be '
              || 'settled. No round was run.'))::text;
  END IF;

  /* WARM THE CACHE BEFORE THE FIRST LOCK (2026-09-09). union_rake_rollup_days
     is a speed cache: a day that is missing is recomputed live and correct,
     but it is recomputed INSIDE the settlement, while it holds treasury rows -
     which is where this union has been deadlocking. Doing it here costs the
     same work at a moment when nothing is locked. A failure is not fatal:
     the live path still answers, just more slowly. */
  BEGIN
    PERFORM public.fn_union_rake_rollup_refresh_day(p_union_id, g.d::date)
       FROM generate_series(v_from::date, (v_to - interval '1 day')::date, interval '1 day') g(d)
      WHERE NOT EXISTS (SELECT 1 FROM public.union_rake_rollup_days rd
                         WHERE rd.union_id = p_union_id AND rd.day = g.d::date)
        AND g.d::date < (now() AT TIME ZONE 'UTC')::date;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'settlement could not warm the rake rollup (%); the live path will answer instead', SQLERRM;
  END;

  IF v_from IS NULL OR NOT isfinite(v_from) OR v_from<>public.fn_union_week_start(v_from)
   OR v_to IS DISTINCT FROM public.fn_union_week_start(v_from+interval '8 days') THEN
   RAISE EXCEPTION 'accounting_preparation_requires_closed_week' USING ERRCODE='22023';
  END IF;
  PERFORM public.fn_union_pnl_closed_book_barrier(v_to);
  -- Serialize every entry point for this union/period. A replay must read
  -- the receipts after the competing transaction commits, before moving chips.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'union-accounting:' || p_union_id::text || ':' || extract(epoch FROM v_from)::text || ':' || extract(epoch FROM v_to)::text, 0));

  -- A union-owned table is not a player's earning club. These outstanding
  -- records are invisible to the member-club join in Round 3. Never certify
  -- completion while they exist, and never guess a replacement beneficiary.
  IF EXISTS (SELECT 1 FROM public.rakeback_periods rp
       WHERE rp.club_id = p_union_id AND rp.status = 'pending'
         AND rp.rakeback_amount > 0
         AND (rp.period_start::timestamp AT TIME ZONE 'America/Los_Angeles') < v_to
         AND ((rp.period_end + 1)::timestamp AT TIME ZONE 'America/Los_Angeles') > v_from) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'union_rakeback_wrong_club',
      DETAIL = 'Pending player rakeback is booked under the union ID. Reconcile the earning-club evidence before settlement.';
  END IF;

  -- THE UNION WALLET IS DEBITED LAST (20260929): round 1 leaves its rake
  -- wallet debit pending for this exact book; it is posted below, after the
  -- statements, so live hands are never queued behind the close.
  -- CHUNKED CLOSE (20261003): a round that commits in its own transaction
  -- posts its own union wallet debit (round 1's original undeferred path):
  -- a pending debit is a transaction-local setting and cannot outlive it.
  PERFORM set_config('app.union_close_defer_rake_debit', CASE WHEN v_chunked THEN '' ELSE p_union_id::text || ':'
    || to_char(v_from AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(v_to AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') END, true);
  PERFORM set_config('app.union_close_pending_rake_debit', '', true);

  -- ROUND 1 - union rake treasury pays the clubs their 90%.
  PERFORM public.fn_assert_cash_commission_period(p_union_id,NULL,v_from,v_to);
  v_preparation:=public.fn_prepare_accounting_week(p_union_id,NULL,v_from,v_to);
  IF v_preparation->>'success' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'weekly_accounting_calculation_incomplete' USING DETAIL=v_preparation::text;
  END IF;
  PERFORM public.fn_weekly_accounting_deadline_check();
  v_r1 := public.fn_union_weekly_rakeback_close(p_union_id, v_from, v_to);
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payers, payees, amount, detail)
  VALUES (p_union_id, v_from, v_to, 1, 'union_to_clubs', 1,
          COALESCE((v_r1->>'clubs_paid')::int,0),
          COALESCE((v_r1->>'total_rakeback')::numeric,0), v_r1)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO NOTHING;

  IF COALESCE((v_r1->>'success')::boolean, false) IS NOT TRUE
     AND COALESCE(v_r1->>'error','') <> 'already_executed' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round1_failed: ' || COALESCE(v_r1->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1,
      'note', 'Rounds 2, 3 and 4 were not run. A club is not asked to pay its '
              || 'agents out of a treasury the union has not funded.'))::text;
  END IF;

  -- CHUNKED CLOSE (20261003): a round that moved money ends this attempt
  -- here; it commits with its receipts (union_rakeback_log, the final
  -- ca_settlements row, union_settlement_rounds round 1) and the next attempt
  -- skips it by them ('already_executed'). Nothing after this point - no
  -- period is marked settled, no statement or square-up is issued - until
  -- the attempt that finds every round committed.
  IF v_chunked AND v_r1->>'success' = 'true' THEN
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 1,
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1);
  END IF;

  -- ROUND 2 - clubs pay their super agents and agents.
  PERFORM public.fn_weekly_accounting_deadline_check();
  -- CHUNKED CLOSE (20261003): a round 2 an earlier attempt committed is
  -- answered from its own receipt - exactly what the stage returns for it
  -- as a duplicate - instead of reading the whole week again to prove it.
  -- Every attempt has first re-run the book's barrier, accrual, refusal and
  -- preparation checks, under which no source of this closed week can change.
  IF v_chunked THEN
    SELECT r.result||jsonb_build_object('duplicate',true) INTO v_r2 FROM public.accounting_routed_settlement_runs r
     WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=2;
  END IF;
  IF v_r2 IS NULL THEN
  v_r2 := public.fn_settle_round2_club_to_agents(p_union_id, v_from, v_to);
  END IF;
  IF v_r2->>'routing_version' IS DISTINCT FROM '3'
    OR v_r2->>'source_version' IS DISTINCT FROM '2'
    OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r
      WHERE r.union_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=2
       AND r.result=(v_r2-'duplicate')) THEN
    RAISE EXCEPTION 'weekly_routing_receipt_not_confirmed' USING ERRCODE='23514';
  END IF;
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, shortfalls, detail)
  VALUES (p_union_id, v_from, v_to, 2, 'club_to_agents',
          COALESCE((v_r2->>'payees')::int,0), COALESCE((v_r2->>'amount')::numeric,0),
          COALESCE((v_r2->>'shortfalls')::int,0), v_r2)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=union_settlement_rounds.detail || jsonb_build_object('latest_attempt',EXCLUDED.detail);

  -- Round 2 carries no 'success' key: it raises on error and returns
  -- {round,name,payees,amount,shortfalls,detail} otherwise, so a test for
  -- 'success' would be unreachable. Assert the CONTRACT instead - a round that
  -- stops reporting an amount must stop the cascade, not record 0 and carry on.
  IF (v_r2->>'amount') IS NULL OR (v_r2->>'payees') IS NULL
     OR (v_r2->>'shortfalls') IS NULL
     OR jsonb_typeof(v_r2->'shortfalls') IS DISTINCT FROM 'number'
     OR (v_r2 ? 'success' AND COALESCE((v_r2->>'success')::boolean, true) IS FALSE
         AND COALESCE(v_r2->>'error','') <> 'already_executed') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round2_contract_violated_or_failed: ' || COALESCE(v_r2->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'note', 'Rounds 3 and 4 were not run.'))::text;
  END IF;

  -- CHUNKED CLOSE (20261003): round 2 commits on its own only with no
  -- shortfall, exactly what the unchunked close would have kept; the next
  -- attempt finds its receipt (accounting_routed_settlement_runs round 2)
  -- and the stage returns it as a duplicate.
  IF v_chunked AND v_r2->>'duplicate' IS DISTINCT FROM 'true' THEN
    IF (v_r2->>'shortfalls')::numeric <> 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success',false,'union_id',p_union_id,
        'error','recipient_shortfalls_remaining','period_start',v_from,'period_end',v_to,
        'round1_union_to_clubs',v_r1,'round2_club_to_agents',v_r2))::text;
    END IF;
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 2,
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2);
  END IF;

  -- ROUND 3 - agents pay their players.
  PERFORM public.fn_weekly_accounting_deadline_check();
  -- CHUNKED CLOSE (20261003): the same for a committed round 3.
  IF v_chunked THEN
    SELECT r.result||jsonb_build_object('duplicate',true) INTO v_r3 FROM public.accounting_routed_settlement_runs r
     WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=3;
  END IF;
  IF v_r3 IS NULL THEN
  v_r3 := public.fn_settle_round3_agents_to_players(p_union_id, v_from, v_to);
  END IF;
  -- CHUNKED CLOSE (20261003, round 3 in batches): a batch that paid part of
  -- round 3 ends this attempt as a committed step; the next attempt pays on.
  IF v_chunked AND v_r3->>'batch_committed' = 'true' THEN
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 3, 'stage', 'round3_batch',
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to, 'round3_batch', v_r3);
  END IF;
  IF v_r3->>'routing_version' IS DISTINCT FROM '3'
    OR v_r3->>'source_version' IS DISTINCT FROM '2'
    OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r
      WHERE r.union_id=p_union_id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=3
       AND r.result=(v_r3-'duplicate')) THEN
    RAISE EXCEPTION 'weekly_routing_receipt_not_confirmed' USING ERRCODE='23514';
  END IF;
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, shortfalls, detail)
  VALUES (p_union_id, v_from, v_to, 3, 'agents_to_players',
          COALESCE((v_r3->>'payees')::int,0), COALESCE((v_r3->>'amount')::numeric,0),
          COALESCE((v_r3->>'shortfalls')::int,0), v_r3)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=union_settlement_rounds.detail || jsonb_build_object('latest_attempt',EXCLUDED.detail);

  -- Same contract assertion for round 3.
  IF (v_r3->>'amount') IS NULL OR (v_r3->>'payees') IS NULL
     OR (v_r3->>'shortfalls') IS NULL
     OR jsonb_typeof(v_r3->'shortfalls') IS DISTINCT FROM 'number'
     OR (v_r3 ? 'success' AND COALESCE((v_r3->>'success')::boolean, true) IS FALSE
         AND COALESCE(v_r3->>'error','') <> 'already_executed') THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round3_contract_violated_or_failed: ' || COALESCE(v_r3->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3,
      'note', 'Round 4 was not run; no statement is issued for a settlement '
              || 'that did not complete.'))::text;
  END IF;

  -- A round can post funded recipients while reporting others still unpaid.
  -- Keep that durable progress, but do not mark the period settled or issue
  -- completion statements until every reported shortfall is zero.
  IF (v_r2->>'shortfalls')::numeric <> 0
     OR (v_r3->>'shortfalls')::numeric <> 0 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success',false,'union_id',p_union_id,
      'error','recipient_shortfalls_remaining','period_start',v_from,'period_end',v_to,
      'round1_union_to_clubs',v_r1,'round2_club_to_agents',v_r2,
      'round3_agents_to_players',v_r3))::text;
  END IF;

  IF EXISTS (SELECT 1 FROM public.rakeback_periods rp
      JOIN public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) uc ON uc.club_id=rp.club_id
      WHERE rp.status='pending' AND rp.rakeback_amount>0
        AND rp.period_start >= (v_from AT TIME ZONE 'America/Los_Angeles')::date
        AND ((rp.period_end+1)::timestamp AT TIME ZONE 'America/Los_Angeles') <= v_to) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='union_player_obligations_remaining';
  END IF;

  -- CONSERVATION, asserted before anything else is written. Raises on a
  -- breach, which rolls this union's whole settlement back.
  PERFORM public.fn_union_settlement_conservation_assert(
            p_union_id, v_from, v_to, v_r1, v_r2, v_r3);

  -- CHUNKED CLOSE (20261003): round 3 commits on its own only after every
  -- test the unchunked close applies to it - no shortfall, no pending player
  -- period, conservation asserted - and the attempt that finds all three
  -- rounds committed repeats those tests before it settles the period.
  IF v_chunked AND v_r3->>'duplicate' IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 3,
      'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3);
  END IF;

  -- club_books_close_after_rakeback: the P&L guard owns the club settlement,
  -- after the earned fee cascade, before statements, ECO or settled status.
  v_quality:=public.fn_union_pnl_close_quality(p_union_id,v_from,v_to);
  IF v_quality->>'status' IS DISTINCT FROM 'ready' THEN
    IF v_chunked AND v_quality->'issues'='["union_pnl_certification_in_progress"]'::jsonb THEN
      RETURN jsonb_build_object('success',false,'chunk_committed',true,'committed_round',0,
        'stage','certifying','purpose','club_settlements','union_id',p_union_id,
        'period_start',v_from,'period_end',v_to,'pnl_evidence',v_quality);
    END IF;
    RAISE EXCEPTION 'union_pnl_basis_uncertified' USING ERRCODE='55000',DETAIL=v_quality::text;
  END IF;

  -- A CLUB STATEMENT'S TOURNAMENT PROOF IS ITS OWN STEP (20261017223358).
  -- Every club statement below proves its club's tournament week, about a
  -- minute a club at Midway's scale, and all of them were proved in the one
  -- attempt that also settles and issues: two clubs did not fit job 272's
  -- 240 s tick, so the 2026-10-05 Midway close could not finish. In a chunked
  -- close each club's READY proof is kept as a close certificate, one club per
  -- attempt, before anything below is settled or issued; the statement reads
  -- it back. A proof that is not ready refuses the statement here, as the
  -- statement itself would. A proof that cannot be kept changes nothing.
  IF v_chunked THEN
    FOR v_credit_club IN SELECT uc.club_id FROM public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) uc
                          WHERE uc.club_id<>p_union_id ORDER BY uc.club_id LOOP
      CONTINUE WHEN public.fn_accounting_close_certificate('club_statement_quality:'||v_credit_club.club_id::text,
        p_union_id,v_from,v_to)->>'status'='ready';
      PERFORM public.fn_weekly_accounting_deadline_check();
      v_quality:=public.fn_accounting_tournament_week_quality(v_credit_club.club_id,v_from,v_to);
      IF v_quality->>'status' IS DISTINCT FROM 'ready' THEN
        RAISE EXCEPTION 'club_weekly_statement_requires_reconciliation' USING ERRCODE='23514',
          DETAIL=jsonb_build_object('club_id',v_credit_club.club_id,'tournament_quality',v_quality)::text;
      END IF;
      PERFORM public.fn_accounting_close_certify('club_statement_quality:'||v_credit_club.club_id::text,
        p_union_id,v_from,v_to,v_quality);
      IF public.fn_accounting_close_certificate('club_statement_quality:'||v_credit_club.club_id::text,
        p_union_id,v_from,v_to)->>'status'='ready' THEN
        RETURN jsonb_build_object('success', false, 'chunk_committed', true, 'committed_round', 3,
          'stage', 'statement_evidence', 'club_id', v_credit_club.club_id,
          'union_id', p_union_id, 'period_start', v_from, 'period_end', v_to);
      END IF;
      EXIT;
    END LOOP;
  END IF;

  -- The period is an accounting object, not a by-product of invoicing.
  PERFORM public.fn_mark_scope_accounting_settled('union',p_union_id,v_from,v_to);

  IF smarter_private.union_eco_terms_for_book(p_union_id,v_from,v_to) IS NOT NULL OR public.fn_union_pnl_qualified_clubs(p_union_id,v_from,v_to)#>>'{eco_commercial_terms_evidence,segments,0,terms,eco_enabled}'='true' THEN
    BEGIN
      v_eco := public.fn_union_eco_record(p_union_id, v_from, v_to, NULL);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT,
                              v_detail = PG_EXCEPTION_DETAIL, v_context = PG_EXCEPTION_CONTEXT;
      v_eco := jsonb_build_object('success', false, 'error', v_msg, 'sqlstate', v_sqlstate,
                                  'exception_detail', v_detail, 'exception_context', v_context);
    END;
  ELSE
    v_eco := jsonb_build_object('skipped', true, 'reason', 'eco_disabled');
  END IF;

  IF v_eco->>'success' = 'false' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'union_eco_record_failed', DETAIL = v_eco::text;
  END IF;

  PERFORM public.fn_weekly_accounting_deadline_check();
  IF public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) <> 1 THEN
    v_inv := jsonb_build_object(
      'success', true, 'skipped', true, 'invoices', 0,
      'reason', 'weekly_invoices_disabled: the union setting weekly_invoices_enabled is 0. '
                || 'Since Phase 6 (20260907) the statement reads the same fn_union_club_rake_basis '
                || 'rows round 1 pays on; switching statements back on is a setting, not a fix.');
  ELSE
    BEGIN
      v_inv := public.fn_union_issue_weekly_invoices(p_union_id, v_from, v_to, true);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT,
                              v_detail = PG_EXCEPTION_DETAIL, v_context = PG_EXCEPTION_CONTEXT;
      v_inv := jsonb_build_object('success', false, 'error', v_msg, 'sqlstate', v_sqlstate,
                                  'exception_detail', v_detail, 'exception_context', v_context);
    END;
  END IF;

  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, detail)
  VALUES (p_union_id, v_from, v_to, 4, 'union_invoices_issued',
          COALESCE((v_inv->>'invoices')::int, 0), 0, v_inv)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=EXCLUDED.detail,payees=EXCLUDED.payees;

  IF COALESCE((v_inv->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'union_settlement_incomplete', DETAIL = (jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round4_invoices_failed: ' || COALESCE(v_inv->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3, 'eco_recorded', v_eco,
      'round4_invoices', v_inv))::text;
  END IF;

  IF COALESCE((v_inv->>'skipped')::boolean, false) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'union_invoices_not_issued', DETAIL = v_inv::text;
  END IF;

  IF EXISTS (SELECT 1 FROM public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) uc
    WHERE uc.club_id<>p_union_id
      AND NOT EXISTS (SELECT 1 FROM public.settlement_invoices si
        WHERE si.club_id=uc.club_id AND si.invoice_type='union_weekly_squareup'
          AND si.breakdown->>'union_id'=p_union_id::text
          AND (si.breakdown->>'period_start')::timestamptz=v_from
          AND (si.breakdown->>'period_end')::timestamptz=v_to
          AND si.message_sent=true AND si.status<>'cancelled')) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='union_invoice_delivery_incomplete';
  END IF;

  -- THE SQUARE-UP'S OWN PERIOD SETTLES WITH ITS WEEK (2026-10-08). The
  -- settler above ran before round 4, and the square-up then opened the
  -- union's own club row (clubs.id = union id) as 'processing', so that one
  -- period never settled (cc6c056b, week of 2026-09-28). Settle every period
  -- this week opened once more, now that the last opener has run, and prove it.
  PERFORM public.fn_mark_scope_accounting_settled('union',p_union_id,v_from,v_to);
  IF EXISTS (SELECT 1 FROM public.settlement_periods sp
              WHERE sp.union_id=p_union_id AND sp.start_at=v_from AND sp.end_at=v_to
                AND sp.status NOT IN ('settled','closed')) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='union_week_period_left_unsettled';
  END IF;

  PERFORM public.fn_weekly_accounting_deadline_check();
  FOR v_credit_club IN SELECT club_id FROM public.fn_accounting_week_clubs(p_union_id,NULL,v_from,v_to) ORDER BY club_id LOOP
    PERFORM public.fn_generate_scope_credit_invoices(v_credit_club.club_id,v_from,v_to);
  END LOOP;
  v_previous_validated:=current_setting('app.union_accounting_validated_period',true);
  PERFORM set_config('app.union_accounting_validated_period',p_union_id::text||':'||v_from::text||':'||v_to::text,true);
  v_club_statements:=public.fn_issue_club_weekly_accounting(p_union_id,v_from,v_to);
  PERFORM public.fn_weekly_accounting_deadline_check();
  PERFORM set_config('app.union_accounting_validated_period',COALESCE(v_previous_validated,''),true);
  v_pending := NULLIF(current_setting('app.union_close_pending_rake_debit', true), '')::jsonb;
  PERFORM set_config('app.union_close_defer_rake_debit', '', true);
  PERFORM set_config('app.union_close_pending_rake_debit', '', true);
  IF v_r1->>'success' = 'true' AND COALESCE((v_r1->>'period_rake')::numeric, 0) > 0 AND (v_pending IS NULL OR v_pending->>'settlement_id' IS DISTINCT FROM v_r1->>'settlement_id') THEN
    RAISE EXCEPTION 'union_close_rake_debit_not_pending' USING ERRCODE='55000';
  END IF;
  IF v_pending IS NOT NULL THEN
    IF v_r1->>'success' IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'union_close_rake_debit_without_round1' USING ERRCODE='55000';
    END IF;
    SELECT * INTO v_posted FROM public.fn_union_close_post_rake_debit(v_pending);
    v_r1 := v_r1 || jsonb_build_object('rake_wallet_after', v_posted.rw_after, 'chip_balance_after', v_posted.cb_after,
      'rake_debit_posted', 'last_write_of_cascade');
  END IF;
  RETURN jsonb_build_object('success', true, 'union_id', p_union_id, 'club_weekly_statements',v_club_statements,
    'period_start', v_from, 'period_end', v_to,
    'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
    'round3_agents_to_players', v_r3, 'eco_recorded', v_eco,
    'round4_invoices', v_inv);
END $function$

public.fn_wheel_pool_seed().def:
CREATE OR REPLACE FUNCTION public.fn_wheel_pool_seed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_seed integer;
BEGIN
  SELECT c.diamond_seed INTO v_seed FROM public.wheel_configs c WHERE c.host_id = NEW.host_id;
  NEW.diamond_seed := COALESCE(v_seed, 0);
  NEW.diamond_float := COALESCE(NEW.diamond_float, 0) + COALESCE(v_seed, 0);
  RETURN NEW;
END $function$

public.log_wallet_transaction(p_user_id.def:
CREATE OR REPLACE FUNCTION public.log_wallet_transaction(p_user_id uuid, p_wallet_type text, p_amount numeric, p_type text, p_category text, p_description text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_original_wallet uuid; v_bal NUMERIC; v_club uuid; v_entry boolean := false;
BEGIN
  /* ZERO-DRIFT (2026-08-31): club members' live balance is
     club_members.chip_balance; public.wallets has been frozen since
     2026-08-21, so reading it stamped a stale balance_after on every row. */
  IF p_wallet_type = 'PLAYER' THEN
    -- Use the debit's union-aware resolver and preferred ledger club. A host
    -- club balance is not the balance of the member wallet actually charged.
    IF p_type = 'debit'
       AND p_related_entity_id IS NOT NULL
       AND lower(COALESCE(p_category, '')) IN
         ('tournament_buyin', 'tournament_rebuy', 'rebuy', 'reentry', 'addon') THEN
      v_entry := true;
      v_club := public.fn_tournament_club_for_user(
        p_user_id,p_related_entity_id,
        NULLIF(current_setting('app.ledger_club_id',true),'')::uuid);
      IF v_club IS NULL THEN
        RAISE EXCEPTION 'Tournament entry receipt has no charged club wallet'
          USING ERRCODE='55000';
      END IF;
    ELSE
      v_club := public.fn_player_home_club(p_user_id, NULL);
    END IF;
    IF v_club IS NOT NULL THEN
      SELECT chip_balance INTO v_bal FROM club_members
       WHERE user_id = p_user_id AND club_id = v_club;
    END IF;
  END IF;
  IF v_entry AND v_bal IS NULL THEN
    RAISE EXCEPTION 'Tournament entry receipt cannot read its charged club wallet'
      USING ERRCODE='55000';
  END IF;
  IF v_bal IS NULL THEN
    SELECT balance INTO v_bal FROM wallets WHERE user_id = p_user_id AND wallet_type = p_wallet_type;
  END IF;
  INSERT INTO wallet_transactions (user_id, wallet_type, amount, type, category, description, table_id, hand_id, related_entity_id, balance_after, created_at)
  VALUES (p_user_id, p_wallet_type, p_amount, p_type, p_category, p_description, p_table_id, p_hand_id, p_related_entity_id, COALESCE(v_bal, 0), NOW()) RETURNING id INTO v_original_wallet;
  PERFORM set_config('app.pnl_tournament_wallet_tx',v_original_wallet::text,true);
END;
$function$

public.process_tournament_rebuy(p_tourna.def:
CREATE OR REPLACE FUNCTION public.process_tournament_rebuy(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_type text:=lower(btrim(COALESCE(p_rebuy_type,'')));
  v_effective_token text;
  v_receipt_key text;
  v_request jsonb;
  v_existing_request jsonb;
  v_existing_response jsonb;
  v_claim jsonb;
  v_response jsonb;
  v_recorded jsonb;
  v_gate jsonb;
  v_choice jsonb;
  v_assignment jsonb;
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate_peek public.tournament_knockout_candidates%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_final_seat public.table_seats%ROWTYPE;
  v_table_id uuid;
  v_seat_number integer;
  v_live_count integer;
  v_pending_count integer;
  v_rebuy_window jsonb;
  v_bounty_settlement jsonb;
  v_bounty_obligation_id uuid;
  v_no_bounty_head boolean:=false;
  v_rows integer;
  v_wake_id bigint;
  v_expected_club_id uuid;
  v_expected_horse_id uuid;
  v_previous_money_path text:=current_setting('app.money_path',true);
BEGIN
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION
      'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player are required'
      USING ERRCODE='22023';
  END IF;
  IF v_type NOT IN ('rebuy','reentry','addon') THEN
    RAISE EXCEPTION 'Invalid rebuy type: %',p_rebuy_type
      USING ERRCODE='22023';
  END IF;
  IF COALESCE(auth.role(),'service_role')<>'service_role'
     AND (auth.uid() IS NULL OR auth.uid()<>p_user_id) THEN
    RAISE EXCEPTION
      'process_tournament_rebuy: caller may only transact for themselves'
      USING ERRCODE='42501';
  END IF;
  IF p_client_token IS NOT NULL
     AND (length(btrim(p_client_token))=0
          OR length(btrim(p_client_token))>128) THEN
    RAISE EXCEPTION 'rebuy prompt token is invalid'
      USING ERRCODE='22023';
  END IF;
  IF v_type<>'addon'
     AND COALESCE(auth.role(),'service_role')<>'service_role'
     AND p_client_token IS NULL THEN
    RAISE EXCEPTION 'a rebuy prompt token is required'
      USING ERRCODE='22023';
  END IF;

  -- Every chip purchase can change the tournament pool, even an add-on that
  -- does not acquire a new chair. Join terminal settlement and maintenance at
  -- their common root before claiming a receipt; an already-committed receipt
  -- can still replay after either boundary without rerunning money.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);

  IF v_type='addon' THEN
    -- Add-ons never create a chair, but their committed receipt must remain
    -- replayable across the maintenance boundary.
    v_receipt_key:='tourney:'||p_tournament_id::text||':addon:'||
      p_user_id::text;
    v_request:=jsonb_build_object(
      'version','v1','tournament_id',p_tournament_id,'user_id',p_user_id,
      'rebuy_type',v_type,'idempotency_key',v_receipt_key);
  ELSIF p_client_token IS NOT NULL
        AND length(btrim(p_client_token))>0 THEN
    v_effective_token:=btrim(p_client_token);
    v_receipt_key:='tourney:'||p_tournament_id::text||':'||v_type||':'||
      p_user_id::text||':tok:'||v_effective_token;
  END IF;

  -- An explicit prompt token names its historical purchase independently of
  -- whichever hand is current now. Read that immutable receipt first, so a
  -- delayed transport retry after later play returns the original answer
  -- instead of trying to bind the token to a newer knockout generation.
  IF v_receipt_key IS NOT NULL THEN
    SELECT r.request,r.response
      INTO v_existing_request,v_existing_response
      FROM public.entry_purchase_idempotency_receipts r
     WHERE r.key_domain='tournament_chip_purchase'
       AND r.idempotency_key=v_receipt_key;
    IF FOUND THEN
      IF v_existing_response IS NULL
         OR v_existing_request->>'version'<>'v1'
         OR v_existing_request->>'tournament_id'<>p_tournament_id::text
         OR v_existing_request->>'user_id'<>p_user_id::text
         OR v_existing_request->>'rebuy_type'<>v_type
         OR v_existing_request->>'idempotency_key'<>v_receipt_key
         OR v_existing_response->>'success'<>'true'
         OR v_existing_response->>'seated'<>'true'
         OR v_existing_response->>'atomic_tournament_chip_purchase'<>'v1'
         OR v_existing_response->>'rebuy_type'<>v_type
         OR v_existing_response->>'table_id' IS NULL
         OR v_existing_response->>'seat_id' IS NULL
         OR v_existing_response->>'stack' IS NULL
         OR (v_type='addon' AND v_existing_request ? 'candidate_id')
         OR (v_type<>'addon' AND (
           v_existing_request->>'candidate_id' IS NULL
           OR v_existing_response->>'candidate_id'<>
              v_existing_request->>'candidate_id'
           OR v_existing_response->>'candidate_state'<>'rebought')) THEN
        RAISE EXCEPTION
          'IDEMPOTENCY_RECEIPT_UNBOUND: historical response is not an atomic tournament purchase proof'
          USING ERRCODE='55000';
      END IF;
      RETURN v_existing_response;
    END IF;
  END IF;

  IF v_type<>'addon' THEN
    -- A rebuy can acquire/revive a chair, so it joins the same global root as
    -- every registration, move and terminal settlement before observing a
    -- candidate. The nonlocking peek derives only an immutable identity; the
    -- exact latest row is re-read under tournament/candidate locks below.
    SELECT * INTO v_candidate_peek
      FROM public.tournament_knockout_candidates c
     WHERE c.id=public.fn_ca_latest_committed_knockout_candidate(
       p_tournament_id,p_user_id);
    IF v_candidate_peek.id IS NULL THEN
      RAISE EXCEPTION
        'REBUY_KNOCKOUT_GENERATION_REQUIRED: no immutable bust authorizes this purchase'
        USING ERRCODE='55000';
    END IF;
    IF v_effective_token IS NULL THEN
      v_effective_token:='candidate:'||v_candidate_peek.id::text;
      v_receipt_key:='tourney:'||p_tournament_id::text||':'||v_type||':'||
        p_user_id::text||':tok:'||v_effective_token;
    END IF;
    v_request:=jsonb_build_object(
      'version','v1','tournament_id',p_tournament_id,'user_id',p_user_id,
      'rebuy_type',v_type,'candidate_id',v_candidate_peek.id,
      'idempotency_key',v_receipt_key);
  END IF;

  v_claim:=public.fn_claim_entry_purchase_receipt(
    'tournament_chip_purchase',v_receipt_key,v_request);
  IF COALESCE((v_claim->>'claimed')::boolean,false) IS NOT TRUE THEN
    v_response:=v_claim->'response';
    IF v_response IS NULL
       OR v_response->>'atomic_tournament_chip_purchase'<>'v1'
       OR v_response->>'success'<>'true'
       OR v_response->>'seated'<>'true'
       OR v_response->>'rebuy_type'<>v_type
       OR v_response->>'table_id' IS NULL
       OR v_response->>'seat_id' IS NULL
       OR v_response->>'stack' IS NULL
       OR (v_type<>'addon' AND
           (v_response->>'candidate_id'<>v_candidate_peek.id::text
            OR v_response->>'candidate_state'<>'rebought')) THEN
      RAISE EXCEPTION
        'IDEMPOTENCY_RECEIPT_UNBOUND: historical response is not an atomic tournament purchase proof'
        USING ERRCODE='55000';
    END IF;
    RETURN v_response;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.wallet_credit_idempotency k
     WHERE k.key=v_receipt_key) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: chip key predates its exact transaction receipt'
      USING ERRCODE='55000';
  END IF;

  IF v_type='addon' THEN
    IF public.fn_entry_purchases_frozen() THEN
      RAISE EXCEPTION
        'PLATFORM_FROZEN: scheduled maintenance has closed add-ons; no chips moved'
        USING ERRCODE='55006';
    END IF;
    SELECT s.table_id INTO v_table_id
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
     ORDER BY s.id
     LIMIT 1;
    IF v_table_id IS NULL THEN
      RAISE EXCEPTION 'Add-on requires one live tournament table'
        USING ERRCODE='55000';
    END IF;
    -- The accepted-hand boundary owns this same table key. During a rolling
    -- database cutover it prevents the old hand body from settling over a paid
    -- grant; after 14534, the hand also takes the terminal root shared before
    -- this key, preserving root -> table -> rows on both paths.
    PERFORM pg_advisory_xact_lock(
      hashtextextended('atomic-table:'||v_table_id::text,0));
    SELECT * INTO v_t FROM public.tournaments t
     WHERE t.id=p_tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found'; END IF;
    IF COALESCE(v_t.prize_pool_finalized,false)
       -- Owner 2026-10-31: no early add-ons, including legacy Free Buy offers.
       -- Historical receipts returned above remain replayable without charging.
       OR upper(COALESCE(v_t.status::text,'')) <> 'RUNNING'
       OR v_t.current_level IS NULL
       OR v_t.current_level<COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)
       OR (COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)<=0
           AND COALESCE(v_t.late_reg_mins,0)>0
           AND (v_t.started_at IS NULL OR
                clock_timestamp()<v_t.started_at+make_interval(mins=>v_t.late_reg_mins)))
       OR (COALESCE(v_t.addon_from_start,false)
           AND v_t.addon_period_ends_at-v_t.addon_period_started_at>interval '60 seconds')
       OR NOT COALESCE(v_t.add_on_available,false)
       OR NOT COALESCE(v_t.addon_period_triggered,false)
       OR v_t.addon_period_started_at IS NULL
       OR v_t.addon_period_ends_at IS NULL
       OR clock_timestamp()<v_t.addon_period_started_at
       OR clock_timestamp()>=v_t.addon_period_ends_at THEN
      RAISE EXCEPTION 'Add-On Period Is Closed Or The Prize Pool Is Already Finalized'
        USING ERRCODE='55000';
    END IF;
    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     FOR UPDATE;
    IF NOT FOUND OR v_player.status::text<>'playing'
       OR COALESCE(v_player.chips,0)<=0 OR COALESCE(v_player.add_on,false) THEN
      RAISE EXCEPTION 'Only one live positive tournament entry may take an add-on'
        USING ERRCODE='55000';
    END IF;
    PERFORM s.id
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL
     ORDER BY s.id FOR UPDATE OF s;
    SELECT count(*)::integer INTO v_live_count
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    IF v_live_count<>1 THEN
      RAISE EXCEPTION 'Add-on requires exactly one locked live tournament seat'
        USING ERRCODE='55000';
    END IF;
    SELECT s.* INTO v_live
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL FOR UPDATE OF s;
    IF v_live.table_id IS DISTINCT FROM v_table_id THEN
      RAISE EXCEPTION 'Add-on live table changed after its atomic-table lock'
        USING ERRCODE='55000';
    END IF;

    -- The Diamond charge's existing order is custody -> profile. Preserve it
    -- without holding the tournament lane behind an unrelated reward claim.
    -- Invalid/missing/closed custody and disabled arenas retain the original
    -- charge's exact refusal; this is only admission for its valid add-on path.
    IF public.fn_ca_tournament_unit_cents(p_tournament_id)=100
       AND v_t.union_id IS NULL
       AND EXISTS (SELECT 1 FROM public.ca_arena_settings a
         WHERE a.id=1 AND a.club_id=v_t.club_id AND a.tournaments_enabled)
       AND (SELECT count(*) FROM public.poker_diamond_custody c
         WHERE c.user_id=p_user_id AND c.purpose='tournament_entry'
           AND c.target_id=p_tournament_id AND c.state<>'released')=1
       AND EXISTS (SELECT 1 FROM public.poker_diamond_custody c
         WHERE c.user_id=p_user_id AND c.purpose='tournament_entry'
           AND c.target_id=p_tournament_id AND c.state='active') THEN
      PERFORM c.id FROM public.poker_diamond_custody c
       WHERE c.user_id=p_user_id AND c.purpose='tournament_entry'
         AND c.target_id=p_tournament_id AND c.state='active'
       FOR UPDATE NOWAIT;
      IF FOUND THEN
        PERFORM 1 FROM public.profiles p WHERE p.id=p_user_id FOR UPDATE NOWAIT;
      END IF;
    END IF;
    v_response:=public.fn_ca_process_tournament_chip_purchase_money_v1(
      p_tournament_id,p_user_id,v_type,p_cost,p_chips,v_t.current_level,
      v_receipt_key);
    IF COALESCE((v_response->>'success')::boolean,false) IS NOT TRUE
       OR COALESCE((v_response->>'idempotent')::boolean,false) THEN
      RAISE EXCEPTION 'tournament add-on money core did not commit a new purchase'
        USING ERRCODE='P0404';
    END IF;
    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
    SELECT s.* INTO v_final_seat FROM public.table_seats s
     WHERE s.id=v_live.id;
    IF v_player.status::text<>'playing' OR NOT COALESCE(v_player.add_on,false)
       OR v_final_seat.left_at IS NOT NULL
       OR v_final_seat.user_id IS DISTINCT FROM p_user_id
       OR v_final_seat.stack IS DISTINCT FROM v_player.chips::numeric
       OR v_final_seat.stack<=0 OR v_final_seat.stack<>trunc(v_final_seat.stack) THEN
      RAISE EXCEPTION 'atomic add-on seat/roster proof is not exact'
        USING ERRCODE='P0404';
    END IF;
    v_wake_id:=public.fn_emit_tournament_manager_wake(p_tournament_id,'addon');
    v_response:=v_response||jsonb_build_object(
      'success',true,'seated',true,'atomic_tournament_chip_purchase','v1',
      'rebuy_type',v_type,'seat_id',v_final_seat.id,
      'table_id',v_final_seat.table_id,
      'seat_number',v_final_seat.seat_number,'stack',v_final_seat.stack,
      'manager_wake_id',v_wake_id);
  ELSE
    v_table_id:=v_candidate_peek.table_id;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('atomic-table:'||v_table_id::text,0));
    -- Preserve the complete acquisition order and refusal precedence before
    -- nonblocking player admission. The original helper reenters these locks.
    PERFORM pg_advisory_xact_lock_shared(530093);
    IF NOT EXISTS(SELECT 1 FROM public.ca_operator_floor_hold h JOIN public.ca_launch_operator_scopes m ON m.operation_id=h.operation_id JOIN public.tournaments t ON t.id=p_tournament_id WHERE h.mode='park' AND (t.club_id=ANY(m.club_ids) OR t.union_id=ANY(m.club_ids)) AND NOT EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=t.id AND tp.user_id=p_user_id)) THEN
      PERFORM pg_advisory_xact_lock_shared(530090,1);
      PERFORM public.fn_ca_lock_mtt_admission_contract();
      IF NOT public.fn_entry_purchases_frozen() THEN
        IF NOT pg_try_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text, 0)) THEN
          RAISE EXCEPTION 'TOURNAMENT_PURCHASE_PLAYER_BUSY: retry this same purchase request'
            USING ERRCODE='55P03';
        END IF;
        IF NOT pg_try_advisory_xact_lock(hashtextextended('daily-missions-user:' || p_user_id::text, 0)) THEN
          RAISE EXCEPTION 'TOURNAMENT_PURCHASE_PLAYER_BUSY: retry this same purchase request'
            USING ERRCODE='55P03';
        END IF;
        IF public.fn_ca_tournament_unit_cents(p_tournament_id)=100 THEN
          -- Its existing custody-add later needs this strongest wallet mode.
          -- Admit it now or refuse before any held KEY SHARE can queue an upgrade.
          PERFORM 1 FROM public.profiles p WHERE p.id=p_user_id FOR UPDATE NOWAIT;
        ELSE
          PERFORM 1 FROM public.profiles p WHERE p.id=p_user_id FOR NO KEY UPDATE NOWAIT;
        END IF;
      END IF;
    END IF;
    v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
      p_tournament_id,NULL,p_user_id);
    IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'tournament rebuy root refused: %',
        COALESCE(v_gate->>'reason','unknown') USING ERRCODE='55000';
    END IF;
    SELECT * INTO v_t FROM public.tournaments t
     WHERE t.id=p_tournament_id;
    IF COALESCE(v_t.prize_pool_finalized,false)
       OR upper(COALESCE(v_t.status::text,''))<>'RUNNING' THEN
      RAISE EXCEPTION 'Tournament is not accepting rebuys or re-entries'
        USING ERRCODE='55000';
    END IF;
    v_rebuy_window:=public.fn_ca_tournament_rebuy_window(p_tournament_id);
    IF COALESCE((v_rebuy_window->>'open')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Rebuy period is closed: %',
        COALESCE(v_rebuy_window->>'reason','unknown') USING ERRCODE='55000';
    END IF;

    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     FOR UPDATE;
    IF NOT FOUND OR v_player.status::text NOT IN ('playing','eliminated')
       OR COALESCE(v_player.chips,0)>0 OR COALESCE(v_player.prize,0)>0 THEN
      RAISE EXCEPTION 'Only the exact unpaid zero-stack entry may rebuy'
        USING ERRCODE='55000';
    END IF;

    PERFORM c.id FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id
     ORDER BY c.hand_number,c.id FOR UPDATE;
    SELECT count(*) FILTER (WHERE c.state='pending')::integer
      INTO v_pending_count
      FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id;
    SELECT * INTO v_candidate
      FROM public.tournament_knockout_candidates c
     WHERE c.id=public.fn_ca_latest_committed_knockout_candidate(
       p_tournament_id,p_user_id);
    IF v_candidate.id IS DISTINCT FROM v_candidate_peek.id
       OR v_candidate.state NOT IN ('pending','eliminated')
       OR (v_candidate.state='pending' AND
           (v_pending_count<>1 OR v_player.status::text<>'playing'))
       OR (v_candidate.state='eliminated' AND
           (v_pending_count<>0 OR v_player.status::text<>'eliminated'))
       OR EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates prior
          WHERE prior.tournament_id=p_tournament_id
            AND prior.eliminated_user_id=p_user_id
            AND (prior.hand_number,prior.id)<
                (v_candidate.hand_number,v_candidate.id)
            AND prior.state<>'rebought') THEN
      RAISE EXCEPTION 'UNRESOLVED_KNOCKOUT_GENERATION_CHAIN'
        USING ERRCODE='P0404';
    END IF;
    IF v_candidate.state='pending'
       AND (v_candidate.rebuy_prompt_until IS NULL
            OR v_candidate.rebuy_prompt_until<=clock_timestamp()) THEN
      RAISE EXCEPTION 'Rebuy or re-entry decision window has closed'
        USING ERRCODE='55000';
    END IF;
    IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
       OR COALESCE(v_t.is_mystery_bounty,false) THEN
      v_bounty_settlement:=
        public.fn_ca_settle_bounty_rebuy_generation_v1(
          p_tournament_id,p_user_id,v_candidate.id);
      -- A MYSTERY REBUY BEFORE THE MONEY HAS NO HEAD TO SETTLE (2026-10-24):
      -- only that exact answer, on a mystery event, may stand in for an
      -- obligation. Every other answer still needs a settled, marked one.
      v_no_bounty_head:=
        COALESCE(v_t.is_mystery_bounty,false)
        AND COALESCE(v_bounty_settlement->>'no_bounty_head','false')='true'
        AND v_bounty_settlement->>'mode'='mystery_pre'
        AND COALESCE(v_bounty_settlement->>'obligation_id','')='';
      BEGIN
        v_bounty_obligation_id:=
          (v_bounty_settlement->>'obligation_id')::uuid;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'Bounty settlement returned no exact generation id'
          USING ERRCODE='P0404';
      END;
      IF COALESCE((v_bounty_settlement->>'ok')::boolean,false) IS NOT TRUE
         OR COALESCE(v_bounty_settlement->>'marker_verified','false')<>'true'
         OR COALESCE(v_bounty_settlement->>'old_head_cleared','false')<>'true'
         OR NOT v_no_bounty_head AND NOT EXISTS (
           SELECT 1 FROM public.tournament_bounty_obligations o
            WHERE o.id=v_bounty_obligation_id
              AND o.tournament_id=p_tournament_id
              AND o.eliminated_user_id=p_user_id
              AND o.hand_number=v_candidate.hand_number
              AND o.hand_id=v_candidate.hand_id
              AND o.state='settled'
              AND public.fn_bounty_obligation_has_complete_marker(o.id)) THEN
        RAISE EXCEPTION
          'Bounty Settlement Pending - Rebuy Or Re-Entry Cannot Replace This Entry Generation Yet'
          USING ERRCODE='55000';
      END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.tournament_obligations o
       WHERE o.tournament_id=p_tournament_id AND o.user_id=p_user_id
         AND o.kind='bubble_protection' AND o.amount_paid=o.amount_owed
         AND o.amount_paid>0 AND o.settled_at IS NOT NULL) THEN
      RAISE EXCEPTION
        'Bubble Protection Already Paid - This Result Cannot Be Resurrected'
        USING ERRCODE='55000';
    END IF;

    PERFORM s.id
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL
     ORDER BY s.id FOR UPDATE OF s;
    SELECT count(*)::integer INTO v_live_count
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    IF v_live_count>1 THEN
      RAISE EXCEPTION 'tournament rebuy found multiple live seats'
        USING ERRCODE='P0404';
    ELSIF v_live_count=1 THEN
      SELECT s.* INTO v_live
        FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
       WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
         AND s.left_at IS NULL FOR UPDATE OF s;
      IF v_live.id IS DISTINCT FROM v_candidate.seat_id
         OR v_live.table_id IS DISTINCT FROM v_candidate.table_id
         OR v_live.joined_at IS DISTINCT FROM v_candidate.seat_joined_at
         OR COALESCE(v_live.stack,0)<>0 THEN
        RAISE EXCEPTION 'knockout generation has a different live seat'
          USING ERRCODE='P0404';
      END IF;
      v_table_id:=v_live.table_id;
      v_seat_number:=v_live.seat_number;
    END IF;

    v_response:=public.fn_ca_process_tournament_chip_purchase_money_v1(
      p_tournament_id,p_user_id,v_type,p_cost,p_chips,v_t.current_level,
      v_effective_token);
    IF COALESCE((v_response->>'success')::boolean,false) IS NOT TRUE
       OR COALESCE((v_response->>'idempotent')::boolean,false) THEN
      RAISE EXCEPTION 'tournament rebuy money core did not commit a new purchase'
        USING ERRCODE='P0404';
    END IF;

    -- A seatless eliminated entry is not counted as active capacity until the
    -- money core promotes it. Choose the chair only after that in-transaction
    -- promotion; any capacity/assignment failure below aborts the debit and
    -- every pool leg with it, so a purchase can never commit seatless.
    IF v_live_count=0 THEN
      v_choice:=public.fn_ca_choose_tournament_seat_locked(
        p_tournament_id,p_user_id,v_candidate.table_id,
        (SELECT s.seat_number FROM public.table_seats s
          WHERE s.id=v_candidate.seat_id));
      v_table_id:=(v_choice->>'table_id')::uuid;
      v_seat_number:=(v_choice->>'seat_number')::integer;
    END IF;

    UPDATE public.tournament_knockout_candidates c
       SET state='rebought',resolved_at=clock_timestamp()
     WHERE c.id=v_candidate.id AND c.state=v_candidate.state
       AND c.state IN ('pending','eliminated');
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'exact knockout generation did not close with its purchase'
        USING ERRCODE='55000';
    END IF;
    UPDATE public.tournament_players tp
       SET rebuy_prompt_until=NULL
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;

    -- An old-pod zero seat can still be live during the rolling window. The
    -- money core fills that locked chair; advancing joined_at begins the new
    -- paid entry generation so a later same-chair bust has a new identity. A
    -- new paid generation is also playable state: clear only lifecycle flags
    -- owned by the expired generation while preserving this player's persisted
    -- time bank and auto-rebuy preference. Naming user_id deliberately reruns
    -- the canonical horse and club stamp triggers for the same occupant.
    IF v_live_count=1 THEN
      v_expected_club_id:=public.fn_seat_club_for_user(
        p_user_id,v_live.table_id,v_player.club_id);
      SELECT CASE WHEN COALESCE(p.is_horse,false) THEN p.id ELSE NULL END
        INTO v_expected_horse_id
        FROM public.profiles p
       WHERE p.id=p_user_id;
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=NULL,member_id=NULL,
             joined_at=clock_timestamp(),status='active',
             is_sitting_out=false,is_away=false,leave_pending=false,
             sit_out_at=NULL,scheduled_leave_hands=NULL,
             horse_id=v_expected_horse_id,club_id=v_expected_club_id,
             entry_hold=NULL,entry_post_agreed=false
       WHERE s.id=v_live.id AND s.left_at IS NULL
         AND s.user_id=p_user_id
         AND s.joined_at=v_candidate.seat_joined_at;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'rebuy could not advance the live seat generation'
          USING ERRCODE='55000';
      END IF;
    END IF;

    v_assignment:=public.fn_ca_assign_tournament_player_seat_locked(
      p_tournament_id,p_user_id,v_table_id,v_seat_number);
    IF COALESCE((v_assignment->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'paid rebuy could not commit its chosen seat: %',
        COALESCE(v_assignment->>'reason','unknown') USING ERRCODE='55000';
    END IF;

    PERFORM s.id
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL
     ORDER BY s.id FOR UPDATE OF s;
    SELECT count(*)::integer INTO v_live_count
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    SELECT s.* INTO v_final_seat
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
    v_expected_club_id:=public.fn_seat_club_for_user(
      p_user_id,v_final_seat.table_id,v_player.club_id);
    SELECT CASE WHEN COALESCE(p.is_horse,false) THEN p.id ELSE NULL END
      INTO v_expected_horse_id
      FROM public.profiles p
     WHERE p.id=p_user_id;
    IF v_live_count<>1 OR v_final_seat.id IS NULL
       OR v_final_seat.stack IS NULL OR v_final_seat.stack<=0
       OR v_final_seat.stack<>trunc(v_final_seat.stack)
       OR v_final_seat.stack IS DISTINCT FROM v_player.chips::numeric
       OR v_final_seat.status::text<>'active'
       OR COALESCE(v_final_seat.is_sitting_out,false)
       OR COALESCE(v_final_seat.is_away,false)
       OR COALESCE(v_final_seat.leave_pending,false)
       OR v_final_seat.sit_out_at IS NOT NULL
       OR v_final_seat.scheduled_leave_hands IS NOT NULL
       OR v_final_seat.entry_hold IS NOT NULL
       OR v_final_seat.entry_post_agreed
       OR v_final_seat.player_id IS NOT NULL
       OR v_final_seat.member_id IS NOT NULL
       OR v_final_seat.horse_id IS DISTINCT FROM v_expected_horse_id
       OR v_final_seat.club_id IS DISTINCT FROM v_expected_club_id
       OR v_player.status::text<>'playing'
       OR v_player.table_id IS DISTINCT FROM v_final_seat.table_id
       OR v_player.seat_number IS DISTINCT FROM v_final_seat.seat_number
       OR ((COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false)) AND (
         (v_bounty_obligation_id IS NULL AND NOT v_no_bounty_head)
         OR round(COALESCE(v_player.current_bounty,0),2) IS DISTINCT FROM
              round(COALESCE((v_response->>'bounty_head_funded')::numeric,0),2)
         OR NOT v_no_bounty_head AND NOT EXISTS (
           SELECT 1 FROM public.tournament_bounty_obligations o
            WHERE o.id=v_bounty_obligation_id AND o.state='settled'
              AND public.fn_bounty_obligation_has_complete_marker(o.id))))
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates c
          WHERE c.id=v_candidate.id AND c.state='rebought')
       OR EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates c
          WHERE c.tournament_id=p_tournament_id
            AND c.eliminated_user_id=p_user_id AND c.state='pending')
       OR NOT EXISTS (
         SELECT 1 FROM public.tables tb
          WHERE tb.id=v_final_seat.table_id
            AND tb.current_players=(
              SELECT count(*) FROM public.table_seats s
               WHERE s.table_id=tb.id AND s.left_at IS NULL)) THEN
      RAISE EXCEPTION 'atomic rebuy candidate/seat/roster proof is not exact'
        USING ERRCODE='P0404';
    END IF;
    v_wake_id:=public.fn_emit_tournament_manager_wake(p_tournament_id,v_type);
    v_response:=v_response||jsonb_build_object(
      'success',true,'seated',true,'atomic_tournament_chip_purchase','v1',
      'rebuy_type',v_type,'candidate_id',v_candidate.id,
      'candidate_state','rebought','seat_id',v_final_seat.id,
      'table_id',v_final_seat.table_id,
      'seat_number',v_final_seat.seat_number,'stack',v_final_seat.stack,
      'prior_bounty_obligation_id',v_bounty_obligation_id,
      'prior_bounty_marker_verified',
        CASE WHEN v_bounty_obligation_id IS NULL THEN NULL ELSE true END,
      'manager_wake_id',v_wake_id);
  END IF;

  v_recorded:=public.fn_record_entry_purchase_receipt(
    'tournament_chip_purchase',v_receipt_key,v_request,v_response);
  IF v_recorded IS DISTINCT FROM v_response THEN
    RAISE EXCEPTION 'atomic tournament chip-purchase receipt changed at commit'
      USING ERRCODE='P0404';
  END IF;
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);
  -- Enqueued in the purchase transaction: rollback publishes nothing.
  -- Receipt replay returns earlier and cannot create a second purchase signal.
  IF v_type='addon' THEN
    PERFORM realtime.send('{}'::jsonb,'purchase_committed',
      'tournament-purchases:'||p_tournament_id::text,true);
  END IF;
  RETURN v_recorded;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);
  RAISE;
END;
$function$

public.trg_ca_club_acct_escrow_certifica.def:
CREATE OR REPLACE FUNCTION public.trg_ca_club_acct_escrow_certificate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'smarter_private'
 SET lock_timeout TO '50ms'
AS $function$
DECLARE v jsonb;
BEGIN
  PERFORM public.fn_ca_club_acct_hand_lock(n.table_id, n.hand_number) FROM new_rows n;
  v := public.fn_ca_club_acct_hand_rows((
    SELECT jsonb_agg(x) FROM public.union_pnl_cash_outcome_touches t
      JOIN new_rows n ON (t.table_id, t.hand_number) = (n.table_id, n.hand_number)
      JOIN public.unions u ON u.id::text = t.game_union_id
     CROSS JOIN LATERAL (VALUES
       (jsonb_build_object('table_id', t.table_id, 'hand_number', t.hand_number, 'recognized_at', t.recognized_at,
          'union_id', u.id, 'sign', 1, 'raked', COALESCE(NULLIF(t.accepted_rake, '')::numeric, 0) > 0,
          'participants', public.fn_union_pnl_posthand_escrow_touch(t))),
       (jsonb_build_object('table_id', t.table_id, 'hand_number', t.hand_number, 'recognized_at', t.recognized_at,
          'union_id', u.id, 'sign', -1, 'raked', COALESCE(NULLIF(t.accepted_rake, '')::numeric, 0) > 0,
          'participants', public.fn_ca_club_acct_unshaped_participants(t)))) s(x)
     WHERE t.shaped));
  PERFORM public.fn_ca_club_acct_put(v->'facts', 0::smallint);
  PERFORM public.fn_ca_club_acct_put_hands(v->'hands', 0::smallint);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    PERFORM public.fn_ca_club_acct_fail('escrow_certificate',
      public.fn_ca_club_acct_day_of_hands(ARRAY(SELECT n.table_id FROM new_rows n), ARRAY(SELECT n.hand_number FROM new_rows n)),
      SQLSTATE || ' ' || SQLERRM || ' hands=' || COALESCE((SELECT string_agg(n.table_id::text || ':' || n.hand_number, ',') FROM new_rows n), ''));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'club data accounting projection could not record its failure: % %', SQLSTATE, SQLERRM;
  END;
  RETURN NULL;
END;
$function$

